window.__Q=window.__Q||{};window.__Q["tcm/3/B1"]=[{"q":"肉苁蓉的功效是","o":["补阴益肾","温脾止泻","润肠通便","清热燥湿","宣肺平喘"],"a":2,"e":"肉苁蓉补肾阳、益精血而润肠通便，善治肾虚精亏之肠燥便秘。补阴益肾项实为熟地黄、山茱萸等滋阴药所长，肉苁蓉重在温阳；温脾止泻项描述的是补骨脂、肉豆蔻，清热燥湿、宣肺平喘更非温阳药之功效"},{"q":"锁阳的功效是","o":["补阴益肾","温脾止泻","润肠通便","清热燥湿","宣肺平喘"],"a":2,"e":"锁阳补肾阳、益精血、润肠通便，与肉苁蓉同类而力稍逊，主治肾虚精亏之便秘。补阴益肾项实为女贞子、旱莲草之属，温脾止泻项属补骨脂，清热燥湿指黄连、黄柏，宣肺平喘则为麻黄、杏仁所主"},{"q":"补骨脂的功效是","o":["补阴益肾","温脾止泻","润肠通便","清热燥湿","宣肺平喘"],"a":1,"e":"补骨脂补肾助阳、固精缩尿、温脾止泻、纳气平喘，温脾止泻为其主治之一，常用于脾肾两虚之五更泄。润肠通便项实为肉苁蓉、锁阳所长，与温脾止泻方向相反；清热燥湿、宣肺平喘分别属黄连类与麻黄类药物"},{"q":"肺、胃出血所致的咯血、吐血，常选用的收敛止血药是","o":["小蓟","白及","三七","槐花","白茅根"],"a":1,"e":"白及质黏收敛，主入肺胃，为止血要药，善治咯血、吐血等肺胃出血。小蓟凉血止血，主治血热妄行之尿血、血淋；槐花清肝凉血，主治下焦血热之痔血便血；三七化瘀止血，偏治外伤瘀肿，均非肺胃出血首选"},{"q":"下焦血热所致的便血、痔血，宜选用的药物是","o":["小蓟","白及","三七","槐花","白茅根"],"a":3,"e":"槐花性寒，清肝泻火、凉血止血，主入大肠，善治下焦血热之便血、痔血。小蓟凉血止血而偏走下焦尿血血淋，白及收敛止血专主肺胃咯血吐血，三七化瘀止血用于外伤瘀肿，病位与病机各异"},{"q":"外伤瘀阻肿痛，宜选用的药物是","o":["小蓟","白及","三七","槐花","白茅根"],"a":2,"e":"三七化瘀止血、活血定痛，止血而不留瘀，为外伤瘀阻肿痛及多种出血的要药。白及收敛止血主肺胃出血，槐花凉血止血主下焦痔血便血，小蓟凉血止血主血热尿血，均无明显活血定痛之功"},{"q":"甘遂与甘草属于","o":["相反","相恶","相须","相杀","相畏"],"a":0,"e":"甘遂与甘草属十八反，同用可增毒性，故为相反。相须指功效相近者协同增效，如石膏配知母；相杀指一药解另一药之毒，如生姜杀半夏毒；相畏系相杀的对应说法，皆不属十八反禁忌之列"},{"q":"牵牛子与巴豆霜属于","o":["相反","相恶","相须","相杀","相畏"],"a":0,"e":"牵牛子与巴豆霜属十九畏，为配伍禁忌，故判相反。相须为同类增效，如大黄配芒硝；相恶指一药破坏另一药功效，如人参恶莱菔子；相杀指减毒，如绿豆杀巴豆毒，均非峻下药之间的禁忌关系"},{"q":"善治毒蛇咬伤，癌肿的药物","o":["白花蛇舌草","地锦草","熊胆粉","白蔹","穿心莲"],"a":0,"e":"白花蛇舌草清热解毒、消痈散结、利湿通淋，现代常用于毒蛇咬伤及癌肿的辅助治疗。地锦草凉血止血、清热解毒，主血热出血及湿热黄疸；熊胆粉清热解毒、明目止惊，主肝热惊风；白蔹收敛消肿，治疮痈溃烂"},{"q":"善治肝热急惊抽搐，目赤的药物是","o":["白花蛇舌草","地锦草","熊胆粉","白蔹","穿心莲"],"a":2,"e":"熊胆粉清热解毒、明目、止惊，主入肝经，善治肝热急惊抽搐及目赤肿痛。白花蛇舌草偏解毒散结、治蛇伤癌肿；白蔹消肿生肌、治疮痈不敛；穿心莲清热燥湿、凉血消肿，均无息风止惊之长"},{"q":"善治疮痈肿痛或溃久不敛的药物是","o":["白花蛇舌草","地锦草","熊胆粉","白蔹","穿心莲"],"a":3,"e":"白蔹清热解毒、消肿止痛、敛疮生肌，善治疮痈肿痛及溃久不敛。白花蛇舌草偏解毒散结、利湿；熊胆粉主清肝明目止惊；地锦草凉血止血，治血热出血；穿心莲清热燥湿，治湿热证，皆无敛疮生肌之能"},{"q":"黄芪配茯苓属于药物七情中的","o":["相须","相使","相反","相畏","相恶"],"a":1,"e":"黄芪补气利水，茯苓健脾渗湿以助黄芪利水消肿，二者主辅相成，属相使。相须为功效相近者并列增效，如石膏配知母；相反为配伍禁忌，如甘遂配甘草；相畏、相恶均非主辅相助关系"},{"q":"人参配五灵脂属于药物七情中的","o":["相须","相使","相反","相畏","相恶"],"a":2,"e":"人参与五灵脂属十九畏，为配伍禁忌，故判相反。相使为主辅相助，如黄芪配茯苓；相须为同类增效，如知母配黄柏；相畏指一药之毒被另一药制约，相恶指功效被破坏，均不属此禁忌对"},{"q":"《新修本草》载药","o":["1500种","365种","730种","1892种","844种"],"a":4,"e":"《新修本草》为唐代官修本草，载药844种，是我国第一部官修药典性本草。365种为《神农本草经》载数，730种属《本草经集注》，1892种是《本草纲目》，分别对应不同本草著作，不可混淆"},{"q":"《本草纲目》载药","o":["1500种","365种","730种","1892种","844种"],"a":3,"e":"《本草纲目》为明代李时珍所撰，载药1892种，集历代本草之大成。844种为《新修本草》所载，730种属《本草经集注》，365种是《神农本草经》，均为更早本草的载药数"},{"q":"墨旱莲的功效有","o":["收敛止血","凉血止血","温经止血","化瘀止血","固经止崩"],"a":1,"e":"墨旱莲滋补肝肾、凉血止血，善治肝肾阴虚兼血热之出血。收敛止血项实为白及、藕节所长，温经止血项属艾叶、炮姜，化瘀止血指三七、茜草，固经止崩则为龟甲、黄芩之类所主"},{"q":"龟甲的功效有","o":["收敛止血","凉血止血","温经止血","化瘀止血","固经止崩"],"a":4,"e":"龟甲滋阴潜阳、益肾健骨、固经止血，善治阴虚血热之崩漏、月经过多。凉血止血项实为墨旱莲、生地所主，收敛止血属白及，温经止血属艾叶，化瘀止血指三七，均非滋阴固经之治"},{"q":"某女，55岁。既患有湿热黄疸，又患有湿疹疮疡，宜选用的药物是","o":["金钱草","茵陈","石韦","萆薢","虎杖"],"a":1,"e":"茵陈利湿退黄、解毒疗疮，为治湿热黄疸要药，兼可治湿疹疮疡。金钱草利湿退黄、排石通淋，主石淋；石韦利尿通淋、清肺止咳；萆薢利湿去浊、祛风舒筋，主膏淋；虎杖利湿退黄兼祛风止痛，偏风湿痹证"},{"q":"某男，45岁。既患有湿热黄疸，又患有风湿痹证，宜选用的药物是","o":["金钱草","茵陈","石韦","萆薢","虎杖"],"a":4,"e":"虎杖利湿退黄、清热解毒、祛风止痛、活血化瘀，既能退黄又治风湿痹痛。茵陈专于利湿退黄、解毒疗疮，无祛风止痛之功；金钱草主排石通淋；石韦主利尿通淋；萆薢主利湿去浊，均不兼风湿痹痛"},{"q":"《神农本草经》论述的是","o":["“若用毒药疗病，先起如黍粟，病去即止……”","“毒药二字……即总括药饵之词“，“解百毒及金石等毒例”","“解百毒及金石等毒例”","“医师聚毒药以供医事”","“毒药攻邪，五谷为养，五果为助……”"],"a":0,"e":"“若用毒药疗病，先起如黍粟，病去即止”出自《神农本草经》序例，强调毒药治病宜从小量开始、中病即止。“医师聚毒药以供医事”出自《周礼》；“解百毒及金石等毒例”为《本草经集注》内容；“毒药二字……总括药饵之词”系后世对毒药含义的概括"},{"q":"《本草经集注》论述的是","o":["“若用毒药疗病，先起如黍粟，病去即止……”","“毒药二字……即总括药饵之词“，“解百毒及金石等毒例”","“解百毒及金石等毒例”","“医师聚毒药以供医事”","“毒药攻邪，五谷为养，五果为助……”"],"a":2,"e":"“解百毒及金石等毒例”为陶弘景《本草经集注》所载，汇列解毒及金石药毒例。“若用毒药疗病，先起如黍粟”出自《神农本草经》；“医师聚毒药以供医事”出自《周礼》；“毒药二字……总括药饵之词”为后世对毒药含义的概括，均非本书内容"},{"q":"石决明主治病证是","o":["阳亢眩晕，心悸失眠","阳亢眩晕，目赤目昏","阳亢眩晕，吐血衄血","阳亢眩晕，湿疹湿疮","阳亢眩晕，肝热急惊"],"a":1,"e":"石决明咸寒，平肝潜阳、清肝明目，主治肝阳上亢之眩晕及目赤目昏。阳亢眩晕兼心悸失眠者为安神药所主，兼吐血衄血者属凉血止血药，兼湿疹湿疮者多清热燥湿药，兼肝热急惊者则归羚羊角、熊胆粉之类"},{"q":"生地黄的功效是","o":["清热凉血，养阴生津","清热凉血，活血散瘀","清热凉血，解毒散结，滋阴降火","清热，解毒，利尿","清热凉血，利尿通淋，解毒疗疮"],"a":0,"e":"生地黄清热凉血、养阴生津，为清热凉血要药，主治热入营血及阴虚内热。清热凉血兼活血散瘀项实为牡丹皮、赤芍所主；解毒散结、滋阴降火指玄参；清热利尿属白茅根、车前子之类，均非生地黄所长"},{"q":"玄参的功效是","o":["清热凉血，养阴生津","清热凉血，活血散瘀","清热凉血，解毒散结，滋阴降火","清热，解毒，利尿","清热凉血，利尿通淋，解毒疗疮"],"a":2,"e":"玄参清热凉血、解毒散结、滋阴降火，善治热入营血、瘰疬痰核及阴虚火旺。养阴生津项实为生地黄所主，活血散瘀指牡丹皮、赤芍，清热利尿属白茅根之类，均非玄参解毒散结、滋阴降火的特点"},{"q":"治温热病气分实热证，宜选用","o":["清热泻火药","清热燥湿药","清热凉血药","清热解毒药","清虚热药"],"a":0,"e":"清热泻火药主清气分实热，善治温热病气分实热之壮热、烦渴、汗出、脉洪大。清热燥湿药主治湿热证，清热凉血药主热入营血，清热解毒药主痈肿疮毒及瘟疫，清虚热药主骨蒸潮热，病位层次各异"},{"q":"治热入营血，宜选用","o":["清热泻火药","清热燥湿药","清热凉血药","清热解毒药","清虚热药"],"a":2,"e":"清热凉血药主入营血，善清血分热邪，主治热入营血之身热夜甚、神昏、斑疹及血热出血。清热泻火药主气分实热，清热燥湿药主湿热，清热解毒药主热毒疮痈，清虚热药主阴虚内热，均非血分专治"},{"q":"相使配伍是","o":["生南星与生姜配伍","黄芪与茯苓配伍","石膏与知母配伍","黄芩与生姜配伍","半夏与附子配伍"],"a":1,"e":"黄芪补气利水，茯苓健脾渗湿助其利水消肿，一主一辅，属相使。生南星与生姜为相杀，生姜解南星之毒；石膏与知母为相须；半夏与附子属相反，均非主辅增效关系"},{"q":"相恶配伍是","o":["生南星与生姜配伍","黄芪与茯苓配伍","石膏与知母配伍","黄芩与生姜配伍","半夏与附子配伍"],"a":3,"e":"黄芩清热燥湿，生姜辛温发散，生姜能削弱黄芩清热之效，属相恶。黄芪与茯苓为相使，石膏与知母为相须，生南星与生姜为相杀，半夏与附子属相反，配伍关系各不相同"},{"q":"具有软坚散结作用的药味是","o":["辛","甘","酸","苦","咸"],"a":4,"e":"咸味能软坚散结、泻下通便，主治瘰疬痰核、癥瘕痞块及便秘。辛味发散行气活血，甘味补益和中调和，酸味收敛固涩，苦味清热燥湿、泄降，均无软坚散结之长"},{"q":"具有补益和中作用的药味是","o":["辛","甘","酸","苦","咸"],"a":1,"e":"甘味能补益、和中、调和药性、缓急止痛，主治虚证及脾胃不和。辛味发散行气，酸味收敛固涩，苦味清热燥湿泄降，咸味软坚散结泻下，四者皆非补益和中之选"},{"q":"羚羊角的功效是","o":["平抑肝阳，息风止痉，清肝明目，清热解毒","凉肝息风，清心豁痰，开窍醒神，清热解毒","安神定惊，明目退翳，解毒生肌，润肤祛斑","平抑肝阳，息风止痉，化痰开窍，清热解毒","凉肝息风，清肝明目，清心豁痰，清热解毒"],"a":0,"e":"羚羊角咸寒，平抑肝阳、息风止痉、清肝明目、清热解毒，主治肝阳上亢、肝风内动及温毒发斑。凉肝息风、清心豁痰、开窍醒神项实为牛黄之功；安神定惊、明目退翳、润肤祛斑项描述的是珍珠，均非羚羊角所具"},{"q":"牛黄的功效是","o":["平抑肝阳，息风止痉，清肝明目，清热解毒","凉肝息风，清心豁痰，开窍醒神，清热解毒","安神定惊，明目退翳，解毒生肌，润肤祛斑","平抑肝阳，息风止痉，化痰开窍，清热解毒","凉肝息风，清肝明目，清心豁痰，清热解毒"],"a":1,"e":"牛黄凉肝息风、清心豁痰、开窍醒神、清热解毒，主治热盛动风、热陷心包及咽喉肿痛。平抑肝阳、清肝明目项实为羚羊角、石决明所长；安神定惊、润肤祛斑项描述的是珍珠，均无豁痰开窍之功"},{"q":"忌食鱼、虾、蟹等腥膻发物和辛辣刺激之品","o":["寒性病","疮疡、皮肤病患者","肝阳上亢者","热性病","胸痹患者"],"a":1,"e":"疮疡、皮肤病患者忌食鱼虾蟹等腥膻发物及辛辣刺激，以免助火动风、加重疮痒。寒性病忌生冷，热性病忌辛辣温燥，肝阳上亢者忌动火升阳之品，胸痹患者忌肥甘厚味，与腥膻发物所忌各异"},{"q":"忌食肥肉、脂肪、动物内脏、烈性酒","o":["寒性病","疮疡、皮肤病患者","肝阳上亢者","热性病","胸痹患者"],"a":4,"e":"胸痹患者忌肥肉、脂肪、动物内脏及烈性酒，以防助湿生痰、壅塞胸阳。寒性病忌生冷，热性病忌温燥辛辣，肝阳上亢者忌辛热升散，疮疡皮肤病者忌腥膻发物，均非胸痹饮食所禁重点"},{"q":"旋覆花入汤剂宜","o":["先煎","后下","包煎","冲服","烊化"],"a":2,"e":"旋覆花为头状花序，表面有绒毛，入汤剂须包煎以免绒毛脱落刺激咽喉。先煎多为矿石贝壳类，后下多为芳香挥发药，冲服用于液体或贵重细粉，烊化用于胶类，皆非旋覆花用法"},{"q":"竹沥入汤剂宜","o":["先煎","后下","包煎","冲服","烊化"],"a":3,"e":"竹沥为竹子加热沥出的液体，性寒滑利，不入煎剂，宜冲服以保存药效。先煎多用于矿石贝壳，后下用于芳香药，包煎用于有毛或细小种子，烊化用于阿胶等胶类，均非竹沥所宜"},{"q":"具有镇惊安神，活血散瘀功效的药物是","o":["琥珀","朱砂","磁石","酸枣仁","夜交藤"],"a":0,"e":"琥珀镇惊安神、活血散瘀、利尿通淋，主治惊悸失眠、瘀血经闭及淋证。朱砂清心镇惊、安神解毒但无活血之功，磁石镇惊安神、平肝潜阳，酸枣仁养心补肝、宁心安神，夜交藤养血安神、祛风通络，均不兼活血散瘀"},{"q":"养肝肾之阴的药物是","o":["玉竹、石斛","百合、麦冬","黄精、天冬","北沙参、玉竹","墨旱莲、女贞子"],"a":4,"e":"墨旱莲、女贞子均能滋补肝肾之阴，为二至丸主药，主治肝肾阴虚之腰膝酸软、须发早白。玉竹、石斛养胃阴，百合、麦冬养心肺之阴，黄精、天冬润肺滋肾，北沙参、玉竹养肺胃阴，归经各异"},{"q":"养心肺之阴的药物是","o":["玉竹、石斛","百合、麦冬","黄精、天冬","北沙参、玉竹","墨旱莲、女贞子"],"a":1,"e":"百合、麦冬均入心肺，养阴润肺、清心生津，善治心肺阴虚之咳嗽、心悸、失眠。玉竹、石斛偏养胃阴，黄精、天冬偏滋肾润肺，北沙参、玉竹养肺胃，墨旱莲、女贞子则专补肝肾，病位不同"},{"q":"既能涩肠，敛肺，又能利咽的药物是","o":["诃子","乌梅","五味子","罂粟壳","五倍子"],"a":0,"e":"诃子涩肠止泻、敛肺止咳、降火利咽，兼能涩肠、敛肺、利咽。乌梅敛肺涩肠并能安蛔，五味子敛肺补肾，五倍子敛肺降火、涩肠止血，罂粟壳敛肺涩肠止痛，均无利咽之长"},{"q":"既能涩肠，敛肺，又能补肾的药物是","o":["诃子","乌梅","五味子","罂粟壳","五倍子"],"a":2,"e":"五味子收敛固涩、益气生津、补肾宁心，既能涩肠、敛肺，又能补肾。诃子偏利咽降火，乌梅偏安蛔生津，五倍子偏敛汗止血，罂粟壳偏止痛，皆无补肾宁心之功"},{"q":"既能涩肠，敛肺，又能安蛔的药物是","o":["诃子","乌梅","五味子","罂粟壳","五倍子"],"a":1,"e":"乌梅敛肺止咳、涩肠止泻、生津止渴、安蛔止痛，既能涩肠敛肺又能安蛔。诃子以利咽为长，五味子以补肾宁心为长，五倍子以敛汗止血为长，罂粟壳以止痛为长，均无安蛔之效"},{"q":"宜烊化的药物是","o":["蜂蜜","蒲黄","阿胶","附子","人参"],"a":2,"e":"阿胶为驴皮熬制的胶类，质黏易粘锅，入汤剂宜烊化兑服，以免焦糊。蒲黄为花粉宜包煎，附子有毒宜先煎，人参贵重宜另煎，蜂蜜则宜冲服，服法各不相同"},{"q":"宜冲服的药物是","o":["蜂蜜","蒲黄","阿胶","附子","人参"],"a":0,"e":"蜂蜜为黏稠液体，遇高温易破坏成分，宜直接用温开水冲服。阿胶为胶类宜烊化，蒲黄细小宜包煎，附子有毒宜先煎，人参贵重宜另煎，均非冲服之法"},{"q":"既平肝潜阳，又清肝明目的药物是","o":["牛黄","蒺藜","龙骨","牡蛎","石决明"],"a":4,"e":"石决明咸寒，平肝潜阳、清肝明目，主治肝阳上亢之头晕目眩及目赤目昏。牛黄主凉肝息风、开窍豁痰，蒺藜平肝疏肝、祛风明目，龙骨、牡蛎重镇安神、平肝潜阳但无清肝明目之功，鉴别要点明确"},{"q":"既平肝疏肝，又祛风止痒的药物是","o":["牛黄","蒺藜","龙骨","牡蛎","石决明"],"a":1,"e":"蒺藜平肝解郁、活血祛风、明目止痒，既能平肝疏肝，又能祛风止痒。牛黄凉肝息风、开窍醒神，龙骨、牡蛎重镇安神、平肝潜阳，石决明平肝潜阳、清肝明目，均无疏肝止痒之能"},{"q":"辛凉药能够","o":["发散风寒","清热燥湿","发散风热","利水渗湿","补气助阳"],"a":2,"e":"辛凉药味辛性凉，能疏散风热，主治风热表证之发热、咽痛、咳嗽。发散风寒属辛温药之功，清热燥湿属苦寒药，利水渗湿多为甘淡药，补气助阳属甘温药，性效各异"},{"q":"甘温药能够","o":["发散风寒","清热燥湿","发散风热","利水渗湿","补气助阳"],"a":4,"e":"甘温药味甘性温，能补气助阳，主治气虚、阳虚之证。发散风寒属辛温解表药，发散风热属辛凉药，清热燥湿属苦寒药，利水渗湿属甘淡渗湿药，均非甘温补益之能"},{"q":"砂仁的功效是","o":["化湿开胃，温脾止泻，理气安胎","化湿和胃，解暑，止呕","化湿行气，解热，止泻","燥湿健脾，祛风湿，行气止痛","化湿行气，温中止呕，开胃消食"],"a":0,"e":"砂仁化湿开胃、温脾止泻、理气安胎，善治湿阻中焦、脾虚泄泻及妊娠恶阻。化湿和胃、解暑止呕项实为藿香所主；化湿行气、温中止呕、开胃消食项描述的是豆蔻；燥湿健脾、祛风湿、行气止痛则为苍术"},{"q":"豆蔻的功效是","o":["化湿开胃，温脾止泻，理气安胎","化湿和胃，解暑，止呕","化湿行气，解热，止泻","燥湿健脾，祛风湿，行气止痛","化湿行气，温中止呕，开胃消食"],"a":4,"e":"豆蔻化湿行气、温中止呕、开胃消食，善治湿温初起及胃寒呕吐。化湿开胃、温脾止泻、理气安胎项实为砂仁；化湿和胃、解暑止呕项属藿香；燥湿健脾、祛风湿、行气止痛项描述的是苍术"},{"q":"淫羊藿的功效是","o":["补肝肾、益精血","补肝肾、续折伤","壮肾阳、托疮毒","补肾阳、安胎元","补肾阳、强筋骨"],"a":4,"e":"淫羊藿补肾阳、强筋骨、祛风湿，善治肾阳虚之筋骨痿软及风湿痹痛。补肝肾、益精血项实为熟地黄、枸杞子所主，补肝肾、续折伤属续断，壮肾阳、托疮毒指鹿茸，补肾阳、安胎元为杜仲所主"},{"q":"巴戟天的功效是","o":["补肝肾、益精血","补肝肾、续折伤","壮肾阳、托疮毒","补肾阳、安胎元","补肾阳、强筋骨"],"a":4,"e":"巴戟天补肾阳、强筋骨、祛风湿，主治肾阳不足之筋骨痿软、风湿痹痛。补肝肾、益精血项实为熟地黄、枸杞子所主，补肝肾、续折伤属续断，壮肾阳、托疮毒指鹿茸，补肾阳、安胎元为杜仲所主"},{"q":"仙茅的功效是","o":["补肝肾、益精血","补肝肾、续折伤","壮肾阳、托疮毒","补肾阳、安胎元","补肾阳、强筋骨"],"a":4,"e":"仙茅补肾阳、强筋骨、祛寒湿，善治肾阳不足、筋骨冷痛。补肝肾、益精血项实为熟地黄、山茱萸所主，补肝肾、续折伤属续断，壮肾阳、托疮毒指鹿茸，补肾阳、安胎元为杜仲所主，功用各有专主"},{"q":"治肺肾两虚、肾不纳气的虚喘，人参常配伍","o":["蛤蚧","防风","黄芪","甘草","西洋参"],"a":0,"e":"蛤蚧补肺益肾、纳气平喘、助阳益精，与人参同用可治肺肾两虚、肾不纳气之虚喘。防风祛风解表，黄芪补气升阳，甘草调和诸药，西洋参补气养阴，均无纳气平喘之功"},{"q":"治表虚自汗而易感风邪者，黄芪、白术常配伍","o":["蛤蚧","防风","黄芪","甘草","西洋参"],"a":1,"e":"防风祛风解表，与黄芪、白术相配即玉屏风散，益气固表止汗，主治表虚自汗易感风邪。蛤蚧纳气平喘，黄芪本为主药而非配伍对象，甘草调和诸药，西洋参补气养阴，皆非固表祛风之选"},{"q":"苦楝皮的功效是","o":["杀虫、疗癣","杀虫、消积","杀虫、利水","杀虫、润肠","杀虫、行气"],"a":0,"e":"苦楝皮杀虫、疗癣，善治蛔虫、蛲虫、钩虫病及头癣体癣。杀虫消积项实为使君子、槟榔所主，杀虫利水属槟榔、南瓜子之类，杀虫润肠指榧子，杀虫行气为川楝子所兼，各有专主"},{"q":"榧子的功效是","o":["杀虫、疗癣","杀虫、消积","杀虫、利水","杀虫、润肠","杀虫、行气"],"a":3,"e":"榧子杀虫消积、润肠通便，善治多种肠道寄生虫并兼便秘。杀虫疗癣项实为苦楝皮所主，杀虫消积属使君子、槟榔，杀虫利水指槟榔，杀虫行气为川楝子所兼，均无润肠之功"},{"q":"木瓜所治疗的病证有","o":["风湿顽痹，麻风疥癣","风湿痹证，骨鲠咽喉","风湿痹证，骨蒸潮热","风湿痹证，吐泻转筋","风寒湿痹，风寒表证"],"a":3,"e":"木瓜舒筋活络、和胃化湿，善治风湿痹痛及吐泻转筋。风湿顽痹、麻风疥癣项实为蕲蛇、乌梢蛇所主；风湿痹证、骨鲠咽喉属威灵仙；骨蒸潮热为秦艽所主；风寒表证则为麻黄、桂枝之类"},{"q":"蕲蛇所治疗的病证有","o":["风湿顽痹，麻风疥癣","风湿痹证，骨鲠咽喉","风湿痹证，骨蒸潮热","风湿痹证，吐泻转筋","风寒湿痹，风寒表证"],"a":0,"e":"蕲蛇祛风通络、定惊止痉，善治风湿顽痹、麻木拘挛及麻风疥癣。骨鲠咽喉项实为威灵仙所主；骨蒸潮热属秦艽；吐泻转筋为木瓜所治；风寒湿痹、风寒表证则属防风、羌活之类"},{"q":"秦艽所治疗的病证有","o":["风湿顽痹，麻风疥癣","风湿痹证，骨鲠咽喉","风湿痹证，骨蒸潮热","风湿痹证，吐泻转筋","风寒湿痹，风寒表证"],"a":2,"e":"秦艽祛风湿、通经络、清虚热、利湿热，善治风湿痹痛兼骨蒸潮热。风湿顽痹、麻风疥癣项实为蕲蛇所主；骨鲠咽喉属威灵仙；吐泻转筋为木瓜所治；风寒表证为防风、羌活所主"},{"q":"百合善治","o":["肠燥便秘","月经过多","腰膝酸软，须发早白","癥瘕积聚，久疟疟母","神志恍惚、行住坐卧不定"],"a":0,"e":"官方答案为【肠燥便秘】，但依据教材，正确答案为【神志恍惚、行住坐卧不定】。百合养阴润肺、清心安神，主肺阴虚咳嗽及百合病，百合病即见神志恍惚、行住坐卧不定；肠燥便秘为麦冬、生地等滋阴药所主，非百合之长。癥瘕积聚、久疟疟母属鳖甲，腰膝酸软、须发早白属旱莲草、女贞子"},{"q":"鳖甲善治","o":["肠燥便秘","月经过多","腰膝酸软，须发早白","癥瘕积聚，久疟疟母","神志恍惚、行住坐卧不定"],"a":3,"e":"鳖甲滋阴潜阳、软坚散结、退热除蒸，善治癥瘕积聚、久疟疟母及阴虚发热。肠燥便秘项实为麦冬、生地所主；神志恍惚、行住坐卧不定属百合病，为百合所治；月经过多、崩漏则多归阿胶、龟甲，均非鳖甲所长"},{"q":"石膏配牛膝属于","o":["相须","相使","相畏","相恶","相反"],"a":1,"e":"石膏清热泻火，牛膝引血下行、助石膏降泄上炎之火，一主一辅，属相使。相须为同类增效，如石膏配知母；相畏指一药之毒被另一药制约；相恶指功效被破坏；相反为配伍禁忌，均非主辅关系"},{"q":"黄连配木香属于","o":["相须","相使","相畏","相恶","相反"],"a":1,"e":"黄连清热燥湿、泻火解毒，木香行气止痛，助黄连行气而止痢，属相使，如香连丸。相须为同类增效，如石膏配知母；相畏为毒性受制；相恶为功效相损；相反为配伍禁忌，皆非本对关系"},{"q":"苍术具有而白术不具有的功效是","o":["健脾燥湿","止汗安胎","祛风散寒","安神益智","补气升阳"],"a":2,"e":"苍术燥湿健脾、祛风散寒、明目，祛风散寒为其独有，白术无此功。健脾燥湿为二者共有；止汗安胎为白术所长，安神益智为远志、龙眼肉所主，补气升阳属黄芪，均非苍术所有"},{"q":"白术具有而苍术不具有的功效是","o":["健脾燥湿","止汗安胎","祛风散寒","安神益智","补气升阳"],"a":1,"e":"白术健脾益气、燥湿利水、止汗、安胎，止汗安胎为其独有，苍术无此功。健脾燥湿为二者共有；祛风散寒、明目为苍术所长；安神益智属远志、龙眼肉；补气升阳为黄芪所主，均非白术功效"},{"q":"妊娠慎用药是","o":["川乌、草乌、三棱、莪术","黄连、桂枝、党参、山药","肉桂、附子、枳实、枳壳","木香、香附、柴胡、前胡","麦冬、玉竹、阿胶、杜仲"],"a":2,"e":"肉桂、附子辛热，枳实、枳壳破气，均可能动胎，属妊娠慎用。川乌、草乌、三棱、莪术毒性峻烈、破血堕胎，为妊娠禁用；黄连、党参、山药等较平和，麦冬、阿胶、杜仲反可安胎，不属慎用之列"},{"q":"妊娠禁用药是","o":["川乌、草乌、三棱、莪术","黄连、桂枝、党参、山药","肉桂、附子、枳实、枳壳","木香、香附、柴胡、前胡","麦冬、玉竹、阿胶、杜仲"],"a":0,"e":"川乌、草乌有大毒，三棱、莪术破血行气峻猛，均能堕胎，属妊娠禁用药。肉桂、附子、枳实、枳壳辛热破气，仅属慎用；黄连、党参、山药等药性平和；木香、香附、柴胡、前胡理气疏肝，麦冬、阿胶、杜仲反能安胎，均非禁用"},{"q":"治疗瘰疬痰核，宜首选的药物是","o":["生地黄","玄参","牡丹皮","赤芍","紫草"],"a":1,"e":"玄参清热凉血、解毒散结、滋阴降火，善治痰火郁结之瘰疬痰核。生地黄养阴生津但无散结之功，牡丹皮、赤芍清热凉血活血，紫草凉血活血解毒、治麻疹紫暗，均非消痰散结之品"},{"q":"西洋参的功效是","o":["补气养阴，清热生津","补脾益肺，养血生津","益气健脾，生津润肺","生津养血，安神益智","补脾养胃，生津益肺"],"a":0,"e":"西洋参补气养阴、清热生津，善治气阴两虚而兼热者。补脾益肺、养血生津项实为党参所主；益气健脾、生津润肺属太子参；生津养血、安神益智指龙眼肉、人参类；补脾养胃、生津益肺为山药所主"},{"q":"山药的功效是","o":["补气养阴，清热生津","补脾益肺，养血生津","益气健脾，生津润肺","生津养血，安神益智","补脾养胃，生津益肺"],"a":4,"e":"山药补脾养胃、生津益肺、补肾涩精，善治脾虚食少、肺虚喘咳及肾虚遗精。补气养阴、清热生津项实为西洋参所主；补脾益肺、养血生津属党参；益气健脾、生津润肺指太子参；生津养血、安神益智为龙眼肉之类"},{"q":"善治乳痈的药物是","o":["穿心莲","鱼腥草","败酱草","蒲公英","野菊花"],"a":3,"e":"蒲公英清热解毒、消痈散结，主入胃肝经，善治乳痈肿痛，为治乳痈要药。穿心莲清热燥湿、凉血消肿；鱼腥草清肺热、治肺痈；败酱草清热解毒、消痈排脓，善治肠痈；野菊花清热解毒，主疔疮痈肿"},{"q":"善治肠痈的药物是","o":["穿心莲","鱼腥草","败酱草","蒲公英","野菊花"],"a":2,"e":"败酱草清热解毒、消痈排脓、祛瘀止痛，善治肠痈腹痛，为治肠痈要药。蒲公英主乳痈；鱼腥草清肺热、治肺痈吐脓；穿心莲清热燥湿；野菊花解毒消肿、治疔疮，均非肠痈专药"},{"q":"我国历史上第一部官修药典性本草是","o":["《本草经集注》","《新修本草》","《本草纲目》","《本草纲目拾遗》","《神农本草经》"],"a":1,"e":"《新修本草》由唐代官府组织编修，载药844种，是我国也是世界上第一部官修药典性本草。《本草经集注》为陶弘景个人所撰，《神农本草经》成于汉代，《本草纲目》《本草纲目拾遗》则为明清著作，均非官修"},{"q":"系统总结了汉代以前我国药学发展的成就，为本草学发展奠定基础的是","o":["《本草经集注》","《新修本草》","《本草纲目》","《本草纲目拾遗》","《神农本草经》"],"a":4,"e":"《神农本草经》系统总结汉代以前药学成就，载药365种，分上中下三品，为本草学发展奠定基础。《本草经集注》为陶弘景所撰，《新修本草》为唐代官修，《本草纲目》《本草纲目拾遗》成于明清，时代均晚"},{"q":"香橼、香附都具有的功效是","o":["降逆止呕","理气调中","行气止痛","温肾纳气","疏肝理气"],"a":4,"e":"香橼、香附均入肝经，都能疏肝理气，主治肝郁气滞之胁胀、月经不调。降逆止呕为半夏、生姜所主；理气调中属陈皮、木香；行气止痛为川楝子、延胡索所长；温肾纳气则属沉香，非二药共有"},{"q":"白扁豆治疗脾虚泄泻，常配伍","o":["滑石","甘草","葛根","山药","香薷"],"a":3,"e":"白扁豆健脾化湿，山药补脾养胃、补肾涩精，二药相配增强健脾止泻之力，善治脾虚泄泻。滑石利尿通淋，甘草调和诸药，葛根升阳止泻兼解肌，香薷发汗解表、化湿和中，均非脾虚泄泻常用配伍"},{"q":"白扁豆治疗夏月乘饮冷，外感于寒，内伤于湿之呕吐、泄泻，常配伍","o":["滑石","甘草","葛根","山药","香薷"],"a":4,"e":"香薷发汗解表、化湿和中，与白扁豆相配，善治夏月外感于寒、内伤于湿之呕吐泄泻。山药健脾止泻，主脾虚久泻；葛根升阳止泻，主脾虚泄泻；滑石、甘草清热利湿，均非夏月感寒伤湿之治"},{"q":"姜黄可用于治疗","o":["风湿痹痛","肝胆湿热","血热出血","心烦失眠","皮肤痒疹"],"a":0,"e":"姜黄活血行气、通经止痛，尤善祛风除痹，主治风湿肩臂疼痛。肝胆湿热项实为龙胆、黄芩所主；血热出血属犀角、生地类；心烦失眠为酸枣仁、栀子所治；皮肤痒疹则多属祛风止痒药，均非姜黄所主"},{"q":"没药可用于治疗","o":["风湿痹痛","肝胆湿热","血热出血","心烦失眠","皮肤痒疹"],"a":0,"e":"没药活血止痛、消肿生肌，善治瘀血阻滞之风湿痹痛、跌打损伤及疮疡肿痛。肝胆湿热项实为龙胆、苦参所主；血热出血属凉血止血药；心烦失眠属安神药；皮肤痒疹属祛风止痒药，均非没药主治"},{"q":"功能祛风发表，胜湿止痛，止痉功效的药物是","o":["白芷","防风","荆芥","麻黄","细辛"],"a":1,"e":"防风祛风解表、胜湿止痛、止痉，善治外感风邪、风湿痹痛及破伤风痉挛。白芷通窍止痛、燥湿止带、消肿排脓；荆芥解表散风、透疹消疮；麻黄发汗解表、宣肺平喘；细辛祛风散寒、通窍、温肺化饮，各有所长"},{"q":"功能祛风散寒，通窍，止痛，温肺化饮的药物是","o":["白芷","防风","荆芥","麻黄","细辛"],"a":4,"e":"细辛祛风散寒、通窍止痛、温肺化饮，善治风寒表证、头痛牙痛及寒饮咳喘。防风祛风胜湿止痉；白芷燥湿止带、消肿排脓；荆芥解表透疹；麻黄发汗平喘、利水消肿，均无温肺化饮之功"},{"q":"功能祛风解表，通窍，止痛，燥湿止带，消肿排脓的药物是","o":["白芷","防风","荆芥","麻黄","细辛"],"a":0,"e":"白芷祛风解表、通窍止痛、燥湿止带、消肿排脓，善治阳明头痛、鼻塞及带下、疮痈。防风胜湿止痛、止痉；细辛温肺化饮；荆芥透疹消疮；麻黄发汗平喘利水，皆无燥湿止带、消肿排脓之能"},{"q":"功能疏肝破气、消积化滞的药物是","o":["枳实","陈皮","香附","青皮","木香"],"a":3,"e":"青皮疏肝破气、消积化滞，善治肝郁气滞之胁痛、疝痛及食积。枳实破气消积、化痰散痞；陈皮理气健脾、燥湿化痰；香附疏肝解郁、理气宽中、调经；木香行气止痛、健脾消食，功各不同"},{"q":"功能破气消积、化痰散痞的药物是","o":["枳实","陈皮","香附","青皮","木香"],"a":0,"e":"枳实破气消积、化痰散痞，善治胃肠积滞、泻痢后重及痰滞胸痞。青皮疏肝破气、消积化滞；陈皮理气健脾燥湿；香附疏肝解郁、调经止痛；木香行气止痛、健脾消食，均无化痰散痞之功"},{"q":"功能疏肝解郁、理气宽中的药物是","o":["枳实","陈皮","香附","青皮","木香"],"a":2,"e":"香附疏肝解郁、理气宽中、调经止痛，为疏肝理气要药，善治肝郁胁痛、月经不调。青皮疏肝破气、消积化滞；枳实破气消积、化痰散痞；陈皮理气健脾；木香行气止痛、健脾消食，均非调经之品"},{"q":"黄柏的主治病证是","o":["肺热咳嗽","肝火头痛","阴虚盗汗","麻风疥癣","胃火牙痛"],"a":2,"e":"黄柏清热燥湿、泻火解毒、退虚热，善治阴虚火旺之骨蒸盗汗、遗精。肺热咳嗽项实为黄芩、桑白皮所主；肝火头痛属龙胆、夏枯草；麻风疥癣为苦参、蕲蛇所治；胃火牙痛则属石膏、黄连，均非黄柏所长"},{"q":"龙胆的主治病证是","o":["肺热咳嗽","肝火头痛","阴虚盗汗","麻风疥癣","胃火牙痛"],"a":1,"e":"龙胆清热燥湿、泻肝胆火，善治肝胆实火之头痛目赤、胁痛口苦及湿热下注。肺热咳嗽项实为黄芩、桑白皮所主；阴虚盗汗属黄柏、知母；麻风疥癣为苦参所治；胃火牙痛属黄连、石膏，病位不同"},{"q":"苦参的主治病证是","o":["肺热咳嗽","肝火头痛","阴虚盗汗","麻风疥癣","胃火牙痛"],"a":3,"e":"苦参清热燥湿、杀虫、利尿，善治湿疹湿疮、皮肤瘙痒及麻风疥癣。肺热咳嗽项实为黄芩、桑白皮所主；肝火头痛属龙胆；阴虚盗汗为黄柏、知母所治；胃火牙痛属黄连、石膏，均无杀虫疗癣之力"},{"q":"临床治疗肠燥便秘尤宜选用的药物有","o":["杜仲、续断、黄芩","肉苁蓉、锁阳、知母","鹿茸、肉苁蓉、山药","淫羊藿、巴戟天、川乌","杜仲、巴戟天、太子参"],"a":1,"e":"肉苁蓉、锁阳均补肾阳、益精血、润肠通便，知母滋阴润燥，三药合用善治肠燥便秘。杜仲、续断、黄芩偏安胎；鹿茸、肉苁蓉、山药补肾健脾；淫羊藿、巴戟天、川乌祛风湿；杜仲、巴戟天、太子参补益，均非润肠之剂"},{"q":"临床治疗胎动不安尤宜选用的药物有","o":["杜仲、续断、黄芩","肉苁蓉、锁阳、知母","鹿茸、肉苁蓉、山药","淫羊藿、巴戟天、川乌","杜仲、巴戟天、太子参"],"a":0,"e":"杜仲、续断补肝肾、强筋骨、安胎，黄芩清热安胎，三药合用善治胎动不安。肉苁蓉、锁阳、知母润肠通便；鹿茸、肉苁蓉、山药补肾；淫羊藿、巴戟天、川乌祛风湿止痛；杜仲、巴戟天、太子参补虚，均非安胎专用"},{"q":"临床治疗风湿痹痛尤宜选用的药物有","o":["杜仲、续断、黄芩","肉苁蓉、锁阳、知母","鹿茸、肉苁蓉、山药","淫羊藿、巴戟天、川乌","杜仲、巴戟天、太子参"],"a":3,"e":"淫羊藿、巴戟天补肾阳、强筋骨、祛风湿，川乌祛风除湿、温经止痛，善治风湿痹痛。杜仲、续断、黄芩安胎；肉苁蓉、锁阳、知母润肠；鹿茸、肉苁蓉、山药补益；杜仲、巴戟天、太子参补虚，均非祛风湿之剂"},{"q":"当归的功效是","o":["补血滋阴，填髓","滋阴潜阳，安神","补血滋阴，止血","补血活血，调经","补血滋阴，柔肝"],"a":3,"e":"当归补血活血、调经止痛、润肠通便，主治血虚萎黄、眩晕心悸及月经不调。补血滋阴、填髓项实为熟地黄所主；滋阴潜阳、安神属龟甲；补血滋阴、止血为阿胶所具；补血滋阴、柔肝为白芍之长"},{"q":"阿胶的功效是","o":["补血滋阴，填髓","滋阴潜阳，安神","补血滋阴，止血","补血活血，调经","补血滋阴，柔肝"],"a":2,"e":"阿胶补血滋阴、润燥、止血，善治血虚萎黄、眩晕心悸及多种出血。补血滋阴、填髓项实为熟地黄所主；滋阴潜阳、安神属龟甲；补血活血、调经为当归所具；补血滋阴、柔肝为白芍之长"},{"q":"熟地黄的功效是","o":["补血滋阴，填髓","滋阴潜阳，安神","补血滋阴，止血","补血活血，调经","补血滋阴，柔肝"],"a":0,"e":"熟地黄补血滋阴、填精益髓，为补血要药，主治血虚萎黄、心悸、月经不调及肝肾阴虚。滋阴潜阳、安神项实为龟甲所主；补血滋阴、止血属阿胶；补血活血、调经为当归；补血滋阴、柔肝为白芍所具"},{"q":"艾叶善治","o":["尿血血淋","痔血便血","崩漏下血","吐血便血","吐血咳血"],"a":2,"e":"艾叶温经止血、散寒调经、安胎，善治虚寒性崩漏下血及月经不调。尿血血淋项实为小蓟、白茅根所主；痔血便血属槐花、地榆；吐血便血为炮姜所治；吐血咳血则属白及，均非温经之剂"},{"q":"白及善治","o":["尿血血淋","痔血便血","崩漏下血","吐血便血","吐血咳血"],"a":4,"e":"白及收敛止血、消肿生肌，主入肺胃，善治咯血、吐血及外伤出血。尿血血淋项实为小蓟、白茅根所主；痔血便血属槐花、地榆；崩漏下血为艾叶所治；吐血便血则属炮姜，病位各异"},{"q":"炮姜善治","o":["尿血血淋","痔血便血","崩漏下血","吐血便血","吐血咳血"],"a":3,"e":"炮姜温经止血、温中止痛，善治脾胃虚寒之吐血、便血及崩漏。尿血血淋项实为小蓟、白茅根所主；痔血便血属槐花、地榆；崩漏下血为艾叶所治；吐血咳血则属白及，均非温中止血之品"},{"q":"苦杏仁的功效为","o":["化痰止咳，活血化瘀","润肺止咳，杀虫灭虱","止咳平喘，利水消肿","宣肺化痰，利咽排脓","降气止咳平喘，润肠通便"],"a":4,"e":"苦杏仁降气止咳平喘、润肠通便，为治咳喘要药，善治咳嗽气喘及肠燥便秘。化痰止咳、活血化瘀项实为矮地茶所主；润肺止咳、杀虫灭虱属百部；止咳平喘、利水消肿指葶苈子；宣肺化痰、利咽排脓为桔梗"},{"q":"百部的功效为","o":["化痰止咳，活血化瘀","润肺止咳，杀虫灭虱","止咳平喘，利水消肿","宣肺化痰，利咽排脓","降气止咳平喘，润肠通便"],"a":1,"e":"百部润肺止咳、杀虫灭虱，善治新久咳嗽及蛲虫、头虱。化痰止咳、活血化瘀项实为矮地茶所主；降气止咳平喘、润肠通便属苦杏仁；止咳平喘、利水消肿指葶苈子；宣肺化痰、利咽排脓为桔梗所具"},{"q":"桔梗的功效为","o":["化痰止咳，活血化瘀","润肺止咳，杀虫灭虱","止咳平喘，利水消肿","宣肺化痰，利咽排脓","降气止咳平喘，润肠通便"],"a":3,"e":"桔梗宣肺、利咽、祛痰、排脓，善治咳嗽痰多、咽痛音哑及肺痈吐脓。化痰止咳、活血化瘀项实为矮地茶所主；润肺止咳、杀虫灭虱属百部；降气止咳平喘、润肠通便为苦杏仁；止咳平喘、利水消肿指葶苈子"},{"q":"矮地茶的功效为","o":["化痰止咳，活血化瘀","润肺止咳，杀虫灭虱","止咳平喘，利水消肿","宣肺化痰，利咽排脓","降气止咳平喘，润肠通便"],"a":0,"e":"矮地茶化痰止咳、清湿热、活血化瘀，善治咳嗽痰多兼瘀血者。润肺止咳、杀虫灭虱项实为百部所主；降气止咳平喘、润肠通便属苦杏仁；宣肺化痰、利咽排脓为桔梗；止咳平喘、利水消肿指葶苈子"},{"q":"既可用于血滞经闭、痛经，又可解蛇虫毒的是","o":["郁金","姜黄","乳香","莪竹","五灵脂"],"a":4,"e":"五灵脂活血止痛、化瘀止血、解毒消肿，善治血滞经闭痛经及蛇虫咬伤。郁金行气解郁、清心凉血；姜黄活血行气、通经止痛；乳香活血止痛、消肿生肌；莪术破血行气、消积止痛，均不解蛇虫毒"},{"q":"可用于热病神昏、癫痫发狂的是","o":["郁金","姜黄","乳香","莪竹","五灵脂"],"a":0,"e":"郁金活血止痛、行气解郁、清心凉血、利胆退黄，善治热病神昏、癫痫发狂。五灵脂活血止痛、解毒消肿；姜黄活血行气、通经止痛；乳香消肿生肌；莪术破血消积，均无清心开窍之功"},{"q":"可用于疮疡肿痛或溃久不收口的是","o":["郁金","姜黄","乳香","莪竹","五灵脂"],"a":2,"e":"乳香活血止痛、消肿生肌，善治疮疡肿痛及溃久不收口。郁金行气解郁、清心凉血；姜黄活血行气、通经止痛；五灵脂化瘀止血、解毒消肿；莪术破血行气、消积止痛，均无生肌敛疮之能"},{"q":"柴胡的主治证是","o":["惊风抽搐","燥热咳嗽","阳毒发斑","酒毒伤中","气滞胁痛"],"a":4,"e":"柴胡解表退热、疏肝解郁、升举阳气，善治肝郁气滞之胁痛、月经不调。惊风抽搐项实为羚羊角、牛黄所主；燥热咳嗽属桑白皮、知母；阳毒发斑为升麻所治；酒毒伤中则属葛根，均非柴胡所主"},{"q":"升麻的主治证是","o":["惊风抽搐","燥热咳嗽","阳毒发斑","酒毒伤中","气滞胁痛"],"a":2,"e":"升麻发表透疹、清热解毒、升举阳气，善治阳毒发斑及麻疹不透。惊风抽搐项实为羚羊角、牛黄所主；燥热咳嗽属知母、桑白皮；酒毒伤中为葛根所解；气滞胁痛属柴胡、香附，各有专主"},{"q":"葛根的主治是","o":["惊风抽搐","燥热咳嗽","阳毒发斑","酒毒伤中","气滞胁痛"],"a":3,"e":"葛根解肌退热、生津止渴、升阳止泻、解酒毒，善治酒毒伤中及项背强痛。惊风抽搐项实为羚羊角、牛黄所主；燥热咳嗽属知母、桑白皮；阳毒发斑为升麻所治；气滞胁痛属柴胡、香附，均非葛根所主"},{"q":"下元虚冷，肾不纳气的虚喘宜用","o":["香附","沉香","薤白","枳实","川楝子"],"a":1,"e":"沉香行气止痛、温中止呕、纳气平喘，善治下元虚冷、肾不纳气之虚喘。香附疏肝理气、调经；薤白通阳散结、行气导滞；枳实破气消积、化痰散痞；川楝子行气止痛、泄肝火，均无纳气平喘之功"},{"q":"肝郁胁痛而兼有热象者宜用","o":["香附","沉香","薤白","枳实","川楝子"],"a":4,"e":"川楝子行气止痛、泄肝火、杀虫疗癣，善治肝郁化火之胁痛。香附疏肝理气但性平无清热之力；沉香温中纳气；薤白通阳散结；枳实破气消积，均不清肝火，非热象胁痛所宜"},{"q":"肠胃气滞之脘腹痞满宜用","o":["香附","沉香","薤白","枳实","川楝子"],"a":3,"e":"枳实破气消积、化痰散痞，善治胃肠气滞之脘腹痞满、泻痢后重。香附疏肝理气、调经；沉香温中止呕、纳气平喘；薤白通阳散结；川楝子行气泄肝火，均非胃肠消积导滞之品"},{"q":"薄荷的功效是","o":["疏散风热，疏肝行气","破血逐瘀，凉血止血","疏散风热，明目退翳","疏散风热，平抑肝阳","散瘀止痛，接骨疗伤"],"a":0,"e":"薄荷疏散风热、清利头目、利咽透疹、疏肝行气，善治风热感冒及肝郁气滞。破血逐瘀、凉血止血项实为三棱、赤芍所主；明目退翳属蝉蜕；平抑肝阳为菊花、桑叶所具；散瘀止痛、接骨疗伤指自然铜、乳香"},{"q":"蝉蜕的功效是","o":["疏散风热，疏肝行气","破血逐瘀，凉血止血","疏散风热，明目退翳","疏散风热，平抑肝阳","散瘀止痛，接骨疗伤"],"a":2,"e":"蝉蜕疏散风热、利咽开音、透疹止痒、明目退翳、息风止痉，善治风热咽痛及目赤翳障。疏肝行气项实为薄荷所主；破血逐瘀、凉血止血属三棱、赤芍；平抑肝阳为菊花所具；散瘀止痛、接骨疗伤指自然铜、乳香"},{"q":"桑叶的功效是","o":["疏散风热，疏肝行气","破血逐瘀，凉血止血","疏散风热，明目退翳","疏散风热，平抑肝阳","散瘀止痛，接骨疗伤"],"a":3,"e":"桑叶疏散风热、清肺润燥、清肝明目，善治风热感冒、肺燥咳嗽及目赤昏花。疏肝行气项实为薄荷所主；明目退翳属蝉蜕；破血逐瘀、凉血止血为赤芍之类；散瘀止痛、接骨疗伤指自然铜、乳香，各有所主"},{"q":"干姜善于治疗","o":["寒饮咳喘","虚寒泄泻","寒凝血瘀证","脾胃虚寒呕吐，呃逆","阴痒，湿疹瘙痒，蛔虫腹痛"],"a":0,"e":"干姜温中散寒、回阳通脉、温肺化饮，善治寒饮伏肺之咳喘及脾胃寒证。虚寒泄泻项实为吴茱萸、补骨脂所主；寒凝血瘀属肉桂；脾胃虚寒呕吐、呃逆为吴茱萸、丁香所治；阴痒、湿疹、蛔虫腹痛则属花椒"},{"q":"吴茱萸善于治疗","o":["寒饮咳喘","虚寒泄泻","寒凝血瘀证","脾胃虚寒呕吐，呃逆","阴痒，湿疹瘙痒，蛔虫腹痛"],"a":1,"e":"吴茱萸散寒止痛、降逆止呕、助阳止泻，善治虚寒泄泻之五更泻及肝胃不和呕吐。寒饮咳喘项实为干姜所主；寒凝血瘀属肉桂；脾胃虚寒呕吐、呃逆为丁香、柿蒂所治；阴痒、湿疹、蛔虫腹痛则属花椒"},{"q":"肉桂善于治疗","o":["寒饮咳喘","虚寒泄泻","寒凝血瘀证","脾胃虚寒呕吐，呃逆","阴痒，湿疹瘙痒，蛔虫腹痛"],"a":2,"e":"肉桂补火助阳、散寒止痛、温通经脉、引火归元，善治寒凝血瘀之痛经、闭经及寒疝。寒饮咳喘项实为干姜所主；虚寒泄泻属吴茱萸、补骨脂；脾胃虚寒呕吐、呃逆为丁香、吴茱萸所治；阴痒、湿疹、蛔虫腹痛则属花椒"},{"q":"花椒善于治疗","o":["寒饮咳喘","虚寒泄泻","寒凝血瘀证","脾胃虚寒呕吐，呃逆","阴痒，湿疹瘙痒，蛔虫腹痛"],"a":4,"e":"花椒温中止痛、杀虫止痒，善治阴痒、湿疹瘙痒及蛔虫腹痛。寒饮咳喘项实为干姜所主；虚寒泄泻属吴茱萸、补骨脂；寒凝血瘀为肉桂所治；脾胃虚寒呕吐、呃逆则属丁香、吴茱萸，均非杀虫止痒之品"},{"q":"莲须的功效是","o":["清心安神","固肾涩精","化瘀止血","清暑化湿","和胃安胎"],"a":1,"e":"莲须固肾涩精，善治肾虚精关不固之遗精、滑精。清心安神项实为莲子心所主；化瘀止血属莲房；清暑化湿为荷叶所具；和胃安胎则属荷梗，同为莲之不同药用部位而功效各异"},{"q":"莲房的功效是","o":["清心安神","固肾涩精","化瘀止血","清暑化湿","和胃安胎"],"a":2,"e":"莲房化瘀止血，善治崩漏、尿血及产后瘀阻出血。固肾涩精项实为莲须所主；清心安神属莲子心；清暑化湿为荷叶所具；和胃安胎则属荷梗，功效各不相同，不可混用"},{"q":"莲子心的功效是","o":["清心安神","固肾涩精","化瘀止血","清暑化湿","和胃安胎"],"a":0,"e":"莲子心清心安神、交通心肾、涩精止血，善治热盛神昏、心烦失眠。固肾涩精项实为莲须所主；化瘀止血属莲房；清暑化湿为荷叶所具；和胃安胎则属荷梗，均非清心之品"},{"q":"荷叶的功效是","o":["清心安神","固肾涩精","化瘀止血","清暑化湿","和胃安胎"],"a":3,"e":"荷叶清暑化湿、升发清阳、凉血止血，善治暑热烦渴及脾虚泄泻。清心安神项实为莲子心所主；固肾涩精属莲须；化瘀止血为莲房所具；和胃安胎则属荷梗，同为莲之部位而功用有别"},{"q":"荷梗的功效是","o":["清心安神","固肾涩精","化瘀止血","清暑化湿","和胃安胎"],"a":4,"e":"荷梗通气宽胸、和胃安胎，善治胸闷不畅及妊娠呕吐、胎动不安。清心安神项实为莲子心所主；固肾涩精属莲须；化瘀止血为莲房所具；清暑化湿则属荷叶，各有所主"},{"q":"金银花既能清热解毒，又能","o":["疏散风热","凉血消斑","泻火定惊","利尿通淋","清热燥湿"],"a":0,"e":"金银花清热解毒、疏散风热，善治温病发热、风热感冒及疮痈肿毒。凉血消斑项实为大青叶、青黛所主；泻火定惊属熊胆、羚羊角；利尿通淋为白茅根、车前子所具；清热燥湿则属黄连、黄芩"},{"q":"穿心莲既能泻火解毒，又能","o":["疏散风热","凉血消斑","泻火定惊","利尿通淋","清热燥湿"],"a":4,"e":"穿心莲清热解毒、凉血、消肿、燥湿，善治湿热泻痢及疮痈肿毒。疏散风热项实为金银花、连翘所主；凉血消斑属大青叶、青黛；泻火定惊为熊胆、羚羊角所具；利尿通淋则属车前子、白茅根"},{"q":"善清心火，用治温病热陷心包，烦躁、神昏的药物是","o":["连翘","鱼腥草","熊胆粉","金银花","山豆根"],"a":0,"e":"连翘清热解毒、消肿散结、疏散风热，主入心经，善清心火，治温病热陷心包之烦躁神昏。清肺热、治肺痈项实为鱼腥草所主；熊胆粉清肝明目止惊；金银花偏疏散风热；山豆根专于利咽，均非清心开窍之品"},{"q":"善清肺热，用治肺痈吐脓的药物是","o":["连翘","鱼腥草","熊胆粉","金银花","山豆根"],"a":1,"e":"鱼腥草清热解毒、消痈排脓、利尿通淋，主入肺经，善清肺热，治肺痈吐脓。清心火、热陷心包项实为连翘所主；熊胆粉清肝止惊；金银花疏散风热；山豆根利咽消肿，均非清肺排脓之品"},{"q":"胖大海的功效是","o":["泻肺平喘，利水消肿","清肺止咳，降逆止呕","清宣肺气，润肠通便","敛肺平喘，止带缩尿","平喘止咳，解痉，定痛"],"a":2,"e":"胖大海清宣肺气、清肠通便、利咽开音，善治肺热声哑、咽喉肿痛及肠燥便秘。泻肺平喘、利水消肿项实为葶苈子所主；清肺止咳、降逆止呕属枇杷叶；敛肺平喘、止带缩尿为白果所具；平喘止咳、解痉定痛则属其他药物"},{"q":"白果的功效是","o":["泻肺平喘，利水消肿","清肺止咳，降逆止呕","清宣肺气，润肠通便","敛肺平喘，止带缩尿","平喘止咳，解痉，定痛"],"a":3,"e":"白果敛肺化痰定喘、止带缩尿，善治哮喘痰多及带下、尿频。泻肺平喘、利水消肿项实为葶苈子所主；清肺止咳、降逆止呕属枇杷叶；清宣肺气、润肠通便为胖大海所具；平喘止咳、解痉定痛则属其他药物"},{"q":"葶苈子的功效是","o":["泻肺平喘，利水消肿","清肺止咳，降逆止呕","清宣肺气，润肠通便","敛肺平喘，止带缩尿","平喘止咳，解痉，定痛"],"a":0,"e":"葶苈子泻肺平喘、利水消肿，善治痰涎壅肺之喘咳及水肿、胸水。清肺止咳、降逆止呕项实为枇杷叶所主；清宣肺气、润肠通便属胖大海；敛肺平喘、止带缩尿为白果所具；平喘止咳、解痉定痛则属其他药物"},{"q":"白芍的功效是","o":["补血滋阴","敛阴止汗","截疟解毒","养血安神","补血活血"],"a":1,"e":"白芍养血敛阴、柔肝止痛、平抑肝阳，善治血虚萎黄、胁肋疼痛及自汗盗汗。补血滋阴项实为熟地黄、阿胶所主；截疟解毒属生何首乌；养血安神为龙眼肉所具；补血活血则属当归，均非敛阴止汗之品"},{"q":"龙眼肉的功效是","o":["补血滋阴","敛阴止汗","截疟解毒","养血安神","补血活血"],"a":3,"e":"龙眼肉补益心脾、养血安神，善治气血不足之心悸怔忡、健忘失眠。补血滋阴项实为熟地黄、阿胶所主；敛阴止汗属白芍；截疟解毒为生何首乌所具；补血活血则属当归，均无养血安神之能"},{"q":"生何首乌的功效是","o":["补血滋阴","敛阴止汗","截疟解毒","养血安神","补血活血"],"a":2,"e":"生何首乌解毒、消痈、截疟、润肠通便，善治疮痈、疟疾及肠燥便秘。补血滋阴项实为熟地黄、阿胶所主；敛阴止汗属白芍；养血安神为龙眼肉所具；补血活血则属当归，功效与制首乌迥异"},{"q":"具有发表透疹，开胃消食功效的药物是","o":["细辛","胡荽","柽柳","麻黄","葱白"],"a":1,"e":"胡荽发表透疹、开胃消食，善治麻疹不透及食积不振。细辛祛风散寒、通窍、温肺化饮；柽柳发表透疹、祛风除湿；麻黄发汗解表、宣肺平喘、利水；葱白发汗解表、散寒通阳，均无开胃消食之功"},{"q":"具有解表透疹，祛风除湿，宣肺止咳功效的药物是","o":["细辛","胡荽","柽柳","麻黄","葱白"],"a":2,"e":"柽柳发表透疹、祛风除湿、宣肺止咳，善治麻疹不透及风湿痹痛。胡荽发表透疹、开胃消食；细辛祛风散寒、温肺化饮；麻黄发汗平喘、利水消肿；葱白散寒通阳，均无祛风除湿、宣肺止咳之能"},{"q":"具有发表解表，散寒通阳功效的药物是","o":["细辛","胡荽","柽柳","麻黄","葱白"],"a":4,"e":"葱白发汗解表、散寒通阳、解毒散结，善治风寒轻证及阴寒腹痛。细辛祛风散寒、通窍、温肺化饮；胡荽透疹、开胃消食；柽柳透疹、祛风除湿；麻黄发汗平喘、利水消肿，均非散寒通阳之品"},{"q":"素有“夏月麻黄”之称的药物是","o":["生姜","香薷","羌活","藁本","防风"],"a":1,"e":"香薷辛微温，发汗解表、化湿和中、利水消肿，夏月感寒湿者用之，故称“夏月麻黄”。白芷祛风通窍、止痛排脓；羌活、防风祛风胜湿；桂枝温通经脉、助阳化气，均无化湿和中、代麻黄解夏月之表之功"},{"q":"素有“呕家圣药”之称的药物是","o":["生姜","香薷","羌活","藁本","防风"],"a":0,"e":"生姜发汗解表、温中止呕、温肺止咳，温中止呕力优，素有“呕家圣药”之称。香薷发汗解表、化湿和中，主夏月感寒；羌活祛风除湿、止痛，主上半身痹痛；藁本祛风胜湿止痛，主巅顶头痛；防风祛风解表、胜湿止痉"},{"q":"素有“治风通用”之称的药物是","o":["生姜","香薷","羌活","藁本","防风"],"a":4,"e":"防风祛风解表、胜湿止痛、止痉，药性平和，为治风通用之品。生姜温中止呕，为呕家圣药；香薷主夏月感寒伤湿；羌活善治上半身风湿痹痛；藁本善治巅顶头痛，各有所专"},{"q":"豨蔹草配臭梧桐的作用是","o":["增强散风寒除湿功效，适用于一身上下风湿痹痛","既能祛风寒湿，又能强腰膝","既能祛风湿通经络，又能降血压","既能祛风除湿，又能活血通络","既能祛风除湿，又能解暑发表"],"a":2,"e":"豨莶草、臭梧桐均能祛风湿、通经络、降血压，二药相须为用，善治风湿痹痛兼高血压。散风寒除湿、治一身上下痹痛项实为独活配羌活；祛风寒湿兼强腰膝属独活配桑寄生；祛风除湿、活血通络为其他配伍"},{"q":"独活配羌活的作用是","o":["增强散风寒除湿功效，适用于一身上下风湿痹痛","既能祛风寒湿，又能强腰膝","既能祛风湿通经络，又能降血压","既能祛风除湿，又能活血通络","既能祛风除湿，又能解暑发表"],"a":0,"e":"羌活善治上半身风湿痹痛，独活善治下半身风湿痹痛，二药相配增强散风寒除湿之力，适用于一身上下风湿痹痛。祛风湿、通经络、降血压项实为豨莶草配臭梧桐；强腰膝属独活配桑寄生；活血通络为其他配伍"},{"q":"独活配桑寄生的作用是","o":["增强散风寒除湿功效，适用于一身上下风湿痹痛","既能祛风寒湿，又能强腰膝","既能祛风湿通经络，又能降血压","既能祛风除湿，又能活血通络","既能祛风除湿，又能解暑发表"],"a":0,"e":"官方答案为【增强散风寒除湿功效，适用于一身上下风湿痹痛】，但依据教材，正确答案为【既能祛风寒湿，又能强腰膝】。桑寄生祛风湿、补肝肾、强筋骨，与独活相配，祛风湿兼强腰膝；一身上下风湿痹痛实为独活配羌活所主，降血压属豨莶草配臭梧桐"},{"q":"连翘的功效是","o":["清热解毒，息风止痉","清热解毒，消痈散结，疏散风热","清热解毒，凉血止痢","清热解毒，截疟","清热解毒，消肿利咽"],"a":1,"e":"连翘清热解毒、消肿散结、疏散风热，善治痈肿疮毒、瘰疬痰核。息风止痉项实为熊胆粉、羚羊角所主；凉血止痢属白头翁、鸦胆子；截疟为青蒿、常山所具；消肿利咽则属山豆根、射干"},{"q":"熊胆粉的功效是","o":["清热解毒，息风止痉","清热解毒，消痈散结，疏散风热","清热解毒，凉血止痢","清热解毒，截疟","清热解毒，消肿利咽"],"a":0,"e":"熊胆粉清热解毒、明目、止惊，善治肝热惊风抽搐及目赤肿痛。消痈散结、疏散风热项实为连翘所主；凉血止痢属白头翁、鸦胆子；截疟为青蒿、常山所具；消肿利咽则属山豆根，均无息风止痉之能"},{"q":"山豆根的功效是","o":["清热解毒，息风止痉","清热解毒，消痈散结，疏散风热","清热解毒，凉血止痢","清热解毒，截疟","清热解毒，消肿利咽"],"a":4,"e":"山豆根清热解毒、利咽消肿，为治咽喉肿痛要药。息风止痉项实为熊胆粉、羚羊角所主；消痈散结、疏散风热属连翘；凉血止痢为白头翁、鸦胆子所具；截疟则属青蒿、常山，均无利咽之长"},{"q":"佛手的功效是","o":["和胃止痛，燥湿化痰","通阳散结，行气导滞","行气宽中，利水消肿","行气散结，祛寒止痛","温中止呕，纳气平喘"],"a":0,"e":"佛手疏肝理气、和胃止痛、燥湿化痰，善治肝郁气滞、胃脘疼痛及痰多咳嗽。通阳散结、行气导滞项实为薤白所主；行气宽中、利水消肿属大腹皮、茯苓皮；行气散结、祛寒止痛为荔枝核、小茴香所具；温中止呕、纳气平喘则属沉香"},{"q":"沉香的功效是","o":["和胃止痛，燥湿化痰","通阳散结，行气导滞","行气宽中，利水消肿","行气散结，祛寒止痛","温中止呕，纳气平喘"],"a":4,"e":"沉香行气止痛、温中止呕、纳气平喘，善治寒凝气滞之胸腹胀痛、胃寒呕吐及肾虚气喘。和胃止痛、燥湿化痰项实为佛手所主；通阳散结、行气导滞属薤白；行气宽中、利水消肿为大腹皮所具；行气散结、祛寒止痛则属荔枝核"},{"q":"薤白的功效是","o":["和胃止痛，燥湿化痰","通阳散结，行气导滞","行气宽中，利水消肿","行气散结，祛寒止痛","温中止呕，纳气平喘"],"a":1,"e":"薤白通阳散结、行气导滞，善治胸痹心痛及胃肠气滞之泻痢后重。和胃止痛、燥湿化痰项实为佛手所主；行气宽中、利水消肿属大腹皮、茯苓皮；行气散结、祛寒止痛为荔枝核、小茴香所具；温中止呕、纳气平喘则属沉香"},{"q":"善治肝胃不和之呕吐的药物是","o":["附子","干姜","肉桂","吴茱萸","小茴香"],"a":3,"e":"吴茱萸散寒止痛、降逆止呕，主入肝胃，善治肝胃不和之呕吐、头痛。附子回阳救逆、补火助阳；干姜温中散寒、温肺化饮；肉桂补火助阳、温通经脉；小茴香祛寒止痛、理气和胃，主寒疝腹痛，均非肝胃不和呕吐首选"},{"q":"善治寒饮伏肺之咳喘的药物是","o":["附子","干姜","肉桂","吴茱萸","小茴香"],"a":1,"e":"干姜温中散寒、温肺化饮，善治寒饮伏肺之咳喘痰多清稀。附子回阳救逆、补火助阳；肉桂补火助阳、引火归元；吴茱萸散寒止痛、降逆止呕；小茴香祛寒止痛、和胃，均无温肺化饮之功"},{"q":"为治寒滞肝经诸痛之主药是","o":["附子","干姜","肉桂","吴茱萸","小茴香"],"a":3,"e":"吴茱萸辛热，主入肝经，散寒止痛力峻，为治寒滞肝经诸痛之主药，善治寒疝腹痛、厥阴头痛、经行腹痛。附子补火助阳、回阳救逆；干姜温中散寒、温肺化饮；肉桂温通经脉、引火归元；小茴香虽治寒疝，力逊且偏理气和胃"},{"q":"为治寒疝腹痛之要药是","o":["附子","干姜","肉桂","吴茱萸","小茴香"],"a":2,"e":"肉桂辛甘大热，归肾、脾、心、肝经，功能补火助阳、散寒止痛、温通经脉，可祛下焦寒凝以止寒疝腹痛。附子长于回阳救逆、补火助阳，主肾阳衰微；干姜温中散寒、回阳通脉，偏治中焦虚寒；吴茱萸散寒止痛、降逆止呕，善治厥阴寒疝、头痛；小茴香散寒理气，亦治寒疝但温阳力弱"},{"q":"味甘、淡，性平的药物是","o":["猪苓","泽泻","薏苡仁","香加皮","冬瓜皮"],"a":0,"e":"猪苓味甘淡、性平，归肾、膀胱经，功能利水渗湿，药性平和而利水之力较强，故性平之说成立。泽泻甘淡寒，兼泻肾与膀胱之热；薏苡仁甘淡凉，兼健脾舒筋；香加皮辛苦温，有毒，能祛风湿强筋骨；冬瓜皮甘凉，兼清热解暑。四者性味各异，唯猪苓平而无寒热偏性"},{"q":"味甘、淡，性寒的药物是","o":["猪苓","泽泻","薏苡仁","香加皮","冬瓜皮"],"a":1,"e":"泽泻味甘淡、性寒，归肾、膀胱经，功能利水渗湿、泄热，善泻肾与膀胱之火，故性寒。猪苓甘淡平，利水而不清热；薏苡仁甘淡凉，健脾为主；香加皮辛苦温，祛风湿强筋骨；冬瓜皮甘凉，清暑热。寒凉之中泄热之力以泽泻为著，性寒之说据此"},{"q":"味甘、淡，性凉的药物是","o":["猪苓","泽泻","薏苡仁","香加皮","冬瓜皮"],"a":2,"e":"薏苡仁味甘淡、性凉，归脾、胃、肺经，功能利水渗湿、健脾止泻、除痹排脓，性凉而能清热。猪苓甘淡平，专于利水；泽泻甘淡寒，泄热力强；香加皮辛苦温，有毒；冬瓜皮甘凉，清暑利水。同为利水药，性凉兼健脾者唯薏苡仁"},{"q":"王不留行的功效是","o":["凉血消斑","润肠通便","清热解毒","舒筋活络","通经下乳"],"a":4,"e":"王不留行苦平，归肝、胃经，功能活血通经、下乳消肿、利尿通淋，善走血分而通乳汁，为通经下乳常用药。鸡血藤补血行血、舒筋活络，主血虚麻木；益母草活血调经、利水消肿、清热解毒，主妇科经产。凉血消斑为牡丹皮之类，润肠通便多属种仁药，清热解毒非其所长"},{"q":"鸡血藤的功效是","o":["凉血消斑","润肠通便","清热解毒","舒筋活络","通经下乳"],"a":3,"e":"鸡血藤苦甘温，归肝、肾经，功能补血行血、通经络，既能补血又能活血通络，故舒筋活络为其所主，常用于血虚麻木、风湿痹痛。王不留行活血通经下乳，无补血之功；益母草活血调经、利水消肿。凉血消斑属牡丹皮、紫草，润肠通便属火麻仁类，清热解毒属金银花类，各有所主"},{"q":"益母草的功效是","o":["凉血消斑","润肠通便","清热解毒","舒筋活络","通经下乳"],"a":2,"e":"益母草辛苦微寒，归肝、心包、膀胱经，功能活血调经、利水消肿、清热解毒，其清热解毒可用于疮痈肿毒、皮肤瘙痒。王不留行活血通经下乳，无解毒之功；鸡血藤补血行血、舒筋活络，性温。凉血消斑为牡丹皮、紫草所主，润肠通便属郁李仁、火麻仁，均与益母草不符"},{"q":"防己的功效是","o":["祛风止痛，止痒","祛风湿，通经络，止泻痢","祛风湿，强筋骨，利水","祛风止痛，利水消肿","舒筋活络，化湿和胃"],"a":3,"e":"防己苦寒，归膀胱、肺经，功能祛风湿、止痛、利水消肿，善治风湿痹痛与水肿脚气，尤宜湿热痹证。老鹳草祛风湿、通经络、止泻痢，无利水之功；五加皮祛风湿、强筋骨、利水，偏于补虚；木瓜舒筋活络、化湿和胃，善治脚气。止痒多为白鲜皮等，非防己所主"},{"q":"老鹳草的功效是","o":["祛风止痛，止痒","祛风湿，通经络，止泻痢","祛风湿，强筋骨，利水","祛风止痛，利水消肿","舒筋活络，化湿和胃"],"a":1,"e":"老鹳草辛苦微温，归肝、大肠经，功能祛风湿、通经络、止泻痢，痹痛兼泻痢者尤为适宜。防己苦寒，祛风止痛、利水消肿；五加皮祛风湿、强筋骨、利水，兼补肝肾；木瓜舒筋活络、化湿和胃。止痒多属白鲜皮、地肤子，非老鹳草所长"},{"q":"五加皮的功效是","o":["祛风止痛，止痒","祛风湿，通经络，止泻痢","祛风湿，强筋骨，利水","祛风止痛，利水消肿","舒筋活络，化湿和胃"],"a":2,"e":"五加皮辛苦温，归肝、肾经，功能祛风湿、补肝肾、强筋骨、利水消肿，为风湿痹痛兼肝肾不足、筋骨痿软所宜。防己苦寒，利水消肿而不补虚；老鹳草通经络、止泻痢；木瓜舒筋活络、化湿和胃。止痒多属祛风止痒药，与五加皮补虚强骨之性不合"},{"q":"补血，柔肝止痛的药物是","o":["白芍","当归","阿胶","生何首乌","制何首乌"],"a":0,"e":"白芍苦酸微寒，归肝、脾经，功能补血调经、柔肝止痛、平抑肝阳，酸收柔润，善治肝郁血虚之胁肋疼痛及拘挛作痛。当归补血活血、调经止痛，偏于温润行血；阿胶补血滋阴、止血润燥；生何首乌截疟解毒、润肠通便；制何首乌补肝肾、益精血、乌须发。柔肝止痛为白芍独有"},{"q":"补血，滋阴润燥的药物是","o":["白芍","当归","阿胶","生何首乌","制何首乌"],"a":2,"e":"阿胶甘平，归肺、肝、肾经，功能补血、滋阴、润燥、止血，为血虚萎黄、阴虚燥咳、各种出血之要药，兼能润燥。白芍补血柔肝止痛、平抑肝阳；当归补血活血调经；生何首乌解毒截疟润肠；制何首乌补肝肾乌须发。滋阴润燥一身而兼止血者，推阿胶"},{"q":"补肝肾，乌须发的药物是","o":["白芍","当归","阿胶","生何首乌","制何首乌"],"a":4,"e":"制何首乌苦甘涩微温，归肝、心、肾经，功能补肝肾、益精血、乌须发、强筋骨，为须发早白、肝肾亏虚常用。生何首乌解毒、截疟、润肠通便，力偏清泄；白芍补血柔肝止痛；当归补血活血调经；阿胶滋阴润燥止血。生制功异，乌须发必用制品"},{"q":"三棱与莪术的主治证是","o":["癥瘕痞块，食积胀痛","瘀血癥瘕，热病神昏","癥瘕经闭，跌打损伤","瘀血癥瘕，疮疡肿痛","瘀血癥瘕，乳汁不下"],"a":0,"e":"三棱、莪术皆辛温行血，功能破血行气、消积止痛，相须为用，善治瘀血癥瘕痞块及食积气滞胀痛。水蛭、虻虫破血逐瘀力强，主瘀血经闭、跌打损伤，无消食之功；穿山甲、王不留行活血通经下乳；其他选项或配热病神昏、或配疮疡肿痛，均非二药主治"},{"q":"水蛭与虻虫的主治证是","o":["癥瘕痞块，食积胀痛","瘀血癥瘕，热病神昏","癥瘕经闭，跌打损伤","瘀血癥瘕，疮疡肿痛","瘀血癥瘕，乳汁不下"],"a":2,"e":"水蛭、虻虫均为破血逐瘀之猛药，功能破血通经、逐瘀消癥，善治瘀血经闭、癥瘕积聚及跌打损伤瘀肿。三棱、莪术破血行气、消食止痛，偏于气滞食积；王不留行、穿山甲活血通经下乳；无汗骨蒸、疮疡肿痛、乳汁不下等皆非二虫所主"},{"q":"王不留行与穿山甲的主治证","o":["癥瘕痞块，食积胀痛","瘀血癥瘕，热病神昏","癥瘕经闭，跌打损伤","瘀血癥瘕，疮疡肿痛","瘀血癥瘕，乳汁不下"],"a":4,"e":"王不留行活血通经、下乳消肿，穿山甲活血消癥、通经下乳，二者均善通乳，主治瘀血癥瘕、经闭及乳汁不下。三棱、莪术破血消积，偏治食积胀痛；水蛭、虻虫破血逐瘀，主跌打损伤；热病神昏属开窍药，疮疡肿痛属清热解毒药，均非二药所长"},{"q":"治疗阴虚火旺，黄柏常配伍的是","o":["苍术","知母","石膏","甘草","栀子"],"a":1,"e":"黄柏苦寒，善泻肾与下焦虚火，配知母滋阴降火、润燥，二药相须，为阴虚火旺、骨蒸潮热、盗汗遗精之常用组合，知柏地黄丸即此意。黄柏配苍术成二妙散，燥湿清热，治湿热下注脚气；配栀子清热利湿退黄，治湿热黄疸；配甘草无降火之功；石膏清气分实热"},{"q":"治疗湿热脚气，黄柏常配伍的是","o":["苍术","知母","石膏","甘草","栀子"],"a":0,"e":"黄柏苦寒清热燥湿，尤清下焦湿热；苍术辛苦温，燥湿健脾、祛风胜湿。二药相伍，一寒一温，燥湿清热，即二妙散，为湿热下注之脚气痿痹、带下、湿疹所常用。配知母滋阴降火，主阴虚火旺；配栀子清热利湿退黄，主湿热黄疸；石膏、甘草均无燥湿治脚气之能"},{"q":"治疗湿热黄疸，黄柏常配伍的是","o":["苍术","知母","石膏","甘草","栀子"],"a":4,"e":"黄柏清热燥湿、泻火除蒸，栀子泻火除烦、清热利湿、凉血解毒，二药合用清热利湿退黄，即栀子柏皮汤之意，治湿热黄疸身黄鲜明。配知母滋阴降火，治阴虚火旺；配苍术燥湿清热，治湿热脚气；石膏清气分实热；甘草调和诸药，无退黄之效"},{"q":"不能与肉桂同用的药物是","o":["郁金","白及","赤石脂","吴茱萸","高良姜"],"a":2,"e":"十九畏载“官桂善能调冷气，若逢石脂便相欺”，肉桂与赤石脂相畏，同用则相互制约、降低药效或增不良反应，故不宜同用。郁金畏丁香而非肉桂；白及反乌头；吴茱萸、高良姜与肉桂虽均温里，但无配伍禁忌，可同用治寒证"},{"q":"哪味中药不能与丁香同用","o":["郁金","白及","赤石脂","吴茱萸","高良姜"],"a":0,"e":"十九畏明言“丁香莫与郁金见”，丁香辛温芳香、温中降逆，郁金辛寒行气活血、清心利胆，二者性味功用相悖且相畏，同用互相牵制，故不宜配伍。赤石脂畏肉桂；白及反乌头；吴茱萸、高良姜与丁香无相反相畏关系，可以同用"},{"q":"有小毒的药物是","o":["郁金","白及","赤石脂","吴茱萸","高良姜"],"a":3,"e":"吴茱萸辛苦热，有小毒，归肝、脾、胃、肾经，功能散寒止痛、降逆止呕、助阳止泻，用量过大易致口干、头晕、腹痛等中毒反应，故标小毒。郁金、白及、赤石脂、高良姜均无毒性记载，其中白及反乌头、郁金畏丁香、赤石脂畏肉桂，皆属配伍禁忌而非自身有毒"},{"q":"哪味中药不能与附子同用","o":["郁金","白及","赤石脂","吴茱萸","高良姜"],"a":1,"e":"十八反歌“本草明言十八反，乌头反半夏瓜蒌贝母白蔹白及”，附子属乌头类，与白及相反，同用可增毒性，故禁同用。郁金畏丁香；赤石脂畏肉桂；吴茱萸、高良姜与附子虽皆温热，但无相反相畏之弊，可依证配伍"},{"q":"性味甘寒，归肺、肝、肾经，功能凉血除蒸，清肺降火的药物是","o":["青蒿","地骨皮","牡丹皮","知母","银柴胡"],"a":1,"e":"地骨皮甘寒，归肺、肝、肾经，功能凉血除蒸、清肺降火，善治阴虚骨蒸潮热、肺热咳嗽及血热出血，性寒而不燥。青蒿苦寒，退虚热、截疟、解暑，善治疟疾寒热；牡丹皮清热凉血、活血散瘀，治无汗骨蒸；知母滋阴降火润燥；银柴胡退虚热、清疳热"},{"q":"治疗阴虚内热，能滋阴润燥的药物是","o":["青蒿","地骨皮","牡丹皮","知母","银柴胡"],"a":3,"e":"知母苦甘寒，归肺、胃、肾经，功能清热泻火、滋阴润燥，上清肺胃实热，下滋肾阴、退虚热，用于阴虚内热、燥咳、消渴、骨蒸潮热。地骨皮凉血除蒸、清肺降火，无滋阴之功；青蒿退虚热截疟；牡丹皮凉血活血；银柴胡退虚热疗疳热，皆不兼润燥"},{"q":"能清热凉血，治疗温病伤阴，无汗骨蒸的药物是","o":["青蒿","地骨皮","牡丹皮","知母","银柴胡"],"a":2,"e":"牡丹皮苦辛微寒，归心、肝、肾经，功能清热凉血、活血化瘀，善入血分，治温病伤阴、热入营血发斑及无汗骨蒸，凉血而不留瘀。地骨皮甘寒，凉血除蒸、清肺降火；青蒿退虚热截疟；知母滋阴降火润燥；银柴胡退虚热、清疳热，均无活血散瘀之能"},{"q":"山楂的性味是","o":["苦，寒","甘，平","辛、甘，平","苦、甘，寒","酸、甘，微温"],"a":4,"e":"山楂酸甘微温，归脾、胃、肝经，功能消食健胃、行气散瘀、化浊降脂，酸甘能开胃助消化，微温可行血散瘀，故性味酸甘微温。苦寒多属清热燥湿药；甘平多为健脾药；辛苦甘平如莱菔子；苦甘寒如某些清热药，均与山楂酸温消食活血之性不符"},{"q":"莱菔子的性味是","o":["苦，寒","甘，平","辛、甘，平","苦、甘，寒","酸、甘，微温"],"a":2,"e":"莱菔子辛甘平，归肺、脾、胃经，功能消食除胀、降气化痰，辛行气、甘和中，性平不偏，善治食积气滞、咳喘痰多。山楂酸甘微温，消食兼散瘀；鸡内金甘平，消食健胃、涩精止遗；苦寒、苦甘寒之品多清热，非消食药常态"},{"q":"鸡内金的性味是","o":["苦，寒","甘，平","辛、甘，平","苦、甘，寒","酸、甘，微温"],"a":1,"e":"鸡内金甘平，归脾、胃、小肠、膀胱经，功能消食健胃、涩精止遗、通淋化石，甘平和缓，消食之力强而不伤正。山楂酸甘微温，行气散瘀；莱菔子辛甘平，降气化痰；苦寒药多清热燥湿，甘平者又有健脾之别，鸡内金以消食化石见长"},{"q":"既能发散风寒，又能利水消肿的药物是","o":["苍耳子","香薷","紫苏叶","羌活","荆芥"],"a":1,"e":"香薷辛微温，归肺、胃、脾经，功能发汗解表、化湿和中、利水消肿，善治夏月外感风寒、内伤暑湿之恶寒发热、吐泻，有“夏月麻黄”之称，故能发散风寒兼利水。苍耳子散风寒、通鼻窍、祛风湿；紫苏叶行气和胃；羌活祛风胜湿止痛；荆芥透疹消疮，均无利水消肿之功"},{"q":"既能发散风寒，又能行气和胃的药物是","o":["苍耳子","香薷","紫苏叶","羌活","荆芥"],"a":2,"e":"紫苏叶辛温，归肺、脾经，功能解表散寒、行气和胃、安胎，既能发散风寒，又善行气宽中、和胃止呕，治风寒感冒兼气滞胸闷、妊娠恶阻。香薷化湿和中、利水消肿；苍耳子通鼻窍；羌活胜湿止痛；荆芥透疹消疮。行气和胃为紫苏叶所长"},{"q":"既能发散风寒，又能透疹消疮的药物是","o":["苍耳子","香薷","紫苏叶","羌活","荆芥"],"a":4,"e":"荆芥辛微温，归肺、肝经，功能解表散风、透疹、消疮，辛散轻扬，既能发散风寒，又可透疹止痒、消疮，治麻疹不透、风疹瘙痒及疮疡初起。香薷利水消肿；紫苏叶行气和胃；苍耳子通鼻窍；羌活祛风胜湿。透疹消疮为荆芥特征"},{"q":"具有散瘀止痛，续筋接骨功效的是","o":["苏木","血竭","土鳖虫","马钱子","自然铜"],"a":4,"e":"自然铜辛平，归肝经，功能散瘀止痛、续筋接骨，为伤科接骨要药，善治跌打损伤、筋伤骨折、瘀肿疼痛。苏木活血祛瘀、消肿止痛，无续骨之功；血竭活血定痛、化瘀止血、敛疮生肌；土鳖虫破血逐瘀、续筋接骨，力在破血；马钱子通络止痛、散结消肿，有大毒"},{"q":"具有破血逐瘀，续筋接骨功效的是","o":["苏木","血竭","土鳖虫","马钱子","自然铜"],"a":2,"e":"土鳖虫咸寒，归肝经，功能破血逐瘀、续筋接骨，善治瘀血经闭、癥瘕痞块及跌打损伤、骨折筋伤。自然铜散瘀止痛、续筋接骨，力偏接骨；苏木活血祛瘀、消肿止痛；血竭化瘀止血、生肌敛疮；马钱子通络止痛、散结消肿，毒性猛烈，非破血逐瘀之品"},{"q":"具有疗伤止痛，补肾强骨功效的是","o":["苏木","血竭","土鳖虫","马钱子","自然铜"],"a":3,"e":"马钱子苦寒有大毒，归肝、脾经，功能通络止痛、散结消肿，善治跌打损伤、骨折瘀肿、风湿顽痹，止痛之力峻猛而能疗伤。自然铜散瘀止痛、续筋接骨；土鳖虫破血逐瘀、续筋接骨；苏木活血祛瘀、消肿止痛；血竭化瘀止血、生肌敛疮。四药虽多伤科用药，补肾强骨、生肌之效各有归属，马钱子专在通络止痛"},{"q":"紫苏子除了止咳平喘外还具有的功效是","o":["利水消肿","降逆止呕","润肠通便","清肠消痔","利咽排脓"],"a":2,"e":"紫苏子辛温，归肺、大肠经，功能降气化痰、止咳平喘、润肠通便，其富含油脂，能润燥滑肠，故咳喘兼便秘者尤宜。桑白皮泻肺平喘、利水消肿；枇杷叶清肺止咳、降逆止呕；马兜铃清肺化痰、止咳平喘、清肠消痔。利水消肿、降逆止呕、清肠消痔皆非紫苏子所有"},{"q":"桑白皮除了泻肺平喘外还具有的功效是","o":["利水消肿","降逆止呕","润肠通便","清肠消痔","利咽排脓"],"a":0,"e":"桑白皮甘寒，归肺经，功能泻肺平喘、利水消肿，善泻肺中水气而平喘，治肺热咳喘、水肿胀满、小便不利。紫苏子降气化痰、止咳平喘、润肠通便；枇杷叶清肺止咳、降逆止呕；马兜铃止咳平喘、清肠消痔。利水消肿为桑白皮特征"},{"q":"枇杷叶除了清肺止咳外还具有的功效是","o":["利水消肿","降逆止呕","润肠通便","清肠消痔","利咽排脓"],"a":1,"e":"枇杷叶苦微寒，归肺、胃经，功能清肺止咳、降逆止呕，胃热呕哕、呃逆者宜之，故除清肺止咳外尚能降逆止呕。桑白皮泻肺平喘、利水消肿；紫苏子降气化痰、润肠通便；马兜铃止咳平喘、清肠消痔。利咽排脓多属桔梗，非枇杷叶所主"},{"q":"马兜铃除了止咳平喘外还具有的功效是","o":["利水消肿","降逆止呕","润肠通便","清肠消痔","利咽排脓"],"a":3,"e":"马兜铃苦微寒，归肺、大肠经，功能清肺化痰、止咳平喘、清肠消痔，肺热咳喘兼痔疮肿痛、便血者宜之。桑白皮泻肺平喘、利水消肿；枇杷叶清肺止咳、降逆止呕；紫苏子降气化痰、润肠通便。利咽排脓属桔梗类，与马兜铃清肠消痔不同"},{"q":"胎动不安、胎漏下血，兼尿血，最宜选用的药物是","o":["桑寄生","苎麻根","砂仁","杜仲","艾叶"],"a":1,"e":"苎麻根甘寒，归心、肝、肾、膀胱经，功能凉血止血、安胎、清热解毒，善治血热所致胎漏下血、胎动不安，兼能利尿而止尿血，故胎动不安兼尿血最宜。桑寄生祛风湿、补肝肾、安胎，无止血尿之功；砂仁化湿行气、温中安胎，主妊娠恶阻；杜仲补肝肾、安胎；艾叶温经止血、散寒安胎，主虚寒"},{"q":"孕期出现的妊娠呕吐，宜选用的药物是","o":["桑寄生","苎麻根","砂仁","杜仲","艾叶"],"a":2,"e":"砂仁辛温，归脾、胃、肾经，功能化湿开胃、温脾止泻、理气安胎，善醒脾和胃、降逆止呕，为妊娠恶阻、呕吐不食常用。苎麻根凉血止血、安胎，主血热胎漏；桑寄生补肝肾、安胎；杜仲补肝肾、强筋骨、安胎；艾叶温经散寒安胎。治妊娠呕吐以砂仁和胃止呕为要"},{"q":"下焦虚寒之胎动不安，宜选用的药物是","o":["桑寄生","苎麻根","砂仁","杜仲","艾叶"],"a":4,"e":"艾叶辛温，归肝、脾、肾经，功能温经止血、散寒调经、安胎，性温散寒，善治下焦虚寒、冲任不固之胎动不安、腹痛、胎漏下血。苎麻根甘寒，凉血安胎，主血热；砂仁理气安胎、化湿止呕；桑寄生、杜仲补肝肾安胎，无温经散寒止血之效"},{"q":"治肝火上炎之目赤肿痛，头痛眩晕，常选用的药物是","o":["栀子","射干","夏枯草","鱼腥草","石膏"],"a":2,"e":"夏枯草苦辛寒，归肝、胆经，功能清肝明目、散结消肿，善清肝火，治肝火上炎之目赤肿痛、头痛眩晕及瘰疬瘿瘤。栀子泻火除烦、清热利湿、凉血解毒，主三焦火；射干清热解毒、祛痰利咽；鱼腥草清热解毒、消痈排脓；石膏清气分实热。清肝明目为夏枯草所长"},{"q":"辛凉走窜，善于治疗热闭神昏证，应首选的药物是","o":["麝香","竹茹","牛黄","石菖蒲","冰片"],"a":4,"e":"冰片辛凉，归心、脾、肺经，功能开窍醒神、清热止痛，辛凉走窜，善治热闭神昏、痰热内闭，点眼吹喉亦可。麝香辛温走窜，寒闭热闭皆宜；牛黄凉，化痰开窍、凉肝息风，主热闭但无辛凉走窜之性；石菖蒲化湿开胃、开窍豁痰，偏治痰湿蒙蔽；竹茹清热化痰、除烦止呕，无开窍之功"},{"q":"辛温走窜，治疗寒闭、热闭神昏证，均可选用的药物是","o":["麝香","竹茹","牛黄","石菖蒲","冰片"],"a":0,"e":"麝香辛温，归心、脾经，功能开窍醒神、活血通经、消肿止痛，辛香走窜力强，为醒神回苏要药，无论寒闭、热闭神昏皆可配伍使用。冰片辛凉，专主热闭；牛黄凉肝化痰开窍，多用于热闭；石菖蒲开窍豁痰、化湿和胃，力较缓；竹茹清热化痰止呕，不治神昏"},{"q":"淡竹叶与竹叶的归经是","o":["心、胃经","肺、胃经","肝、胆经","心、胃、小肠经","肺、胃、肾经"],"a":3,"e":"淡竹叶与竹叶均甘淡寒，归心、胃、小肠经，功能清热除烦、利尿，善清心胃之热兼利小便，故归经为心、胃、小肠。单归心、胃经者未及小肠利水；肺、胃经为芦根、天花粉之属；肝、胆经多清肝药；肺、胃、肾经为知母、天门冬类，均非二竹所归"},{"q":"芦根与天花粉的归经是","o":["心、胃经","肺、胃经","肝、胆经","心、胃、小肠经","肺、胃、肾经"],"a":1,"e":"芦根与天花粉均甘寒，归肺、胃经，都能清热生津，芦根兼除烦止呕、利尿，天花粉兼消肿排脓，归经同属肺胃。心、胃、小肠经为淡竹叶、竹叶所归；心、胃经多清心火之品；肝、胆经属清肝药；肺、胃、肾经为知母、黄精类，非二药所归"},{"q":"能减轻或消除毒副作用的配伍是","o":["相须","相使","相杀","相恶","相反"],"a":2,"e":"相杀指一种药物能减轻或消除另一种药物的毒副作用，如生姜杀半夏毒、绿豆杀巴豆毒，重在以一药制另一药之毒。相须为性能功效相似者协同增效；相使为以一药为主、另一药辅之而增效；相恶为相互拮抗、削弱功效；相反为合用产生或增强毒性"},{"q":"能产生或增强毒副作用的配伍是","o":["相须","相使","相杀","相恶","相反"],"a":4,"e":"相反指两药合用能产生或增强毒副作用，属配伍禁忌，如乌头反半夏、甘草反甘遂、藜芦反人参，即十八反所载。相杀是减轻消除毒性；相须协同增效；相使主辅相成；相恶相互拮抗、降低药效但不增毒，与相反有本质区别"},{"q":"治疗外感风寒之巅顶头痛，宜首选的药物是","o":["蔓荆子","防风","细辛","藁本","白芷"],"a":3,"e":"藁本辛温，归膀胱经，功能祛风散寒、除湿止痛，善达巅顶，为治外感风寒、巅顶头痛之要药，兼治风湿痹痛。蔓荆子疏散风热、清利头目，主风热头痛；防风祛风解表、胜湿止痛，善治周身风湿；细辛祛风散寒、通窍止痛，主少阴头痛；白芷祛风解表、通鼻窍，主阳明眉棱骨痛"},{"q":"治疗外感风寒之眉棱骨痛，宜首选的药物是","o":["蔓荆子","防风","细辛","藁本","白芷"],"a":4,"e":"白芷辛温，归胃、大肠、肺经，功能解表散寒、祛风止痛、通鼻窍、燥湿止带、消肿排脓，善入阳明经，为治眉棱骨痛、阳明头痛之要药。藁本主巅顶头痛；蔓荆子主风热头目痛；防风胜湿止痛；细辛通窍止痛，主少阴头痛。引经不同，痛处各异"},{"q":"治风寒咳嗽，甘草常配伍","o":["麻黄、杏仁","干姜、细辛","半夏、陈皮","石膏、黄芩","知母、川贝母"],"a":0,"e":"麻黄发汗解表、宣肺平喘，杏仁降气止咳，甘草润肺和中、调和诸药，三药相合即三拗汤，辛温发散、宣降肺气，为风寒咳嗽、气喘之基础方。干姜、细辛温肺化饮，主寒痰咳嗽；半夏、陈皮燥湿化痰、理气和中，主湿痰；石膏、黄芩清泻肺热；知母、川贝母润肺止咳，治阴虚燥咳"},{"q":"治寒痰咳嗽，甘草常配伍","o":["麻黄、杏仁","干姜、细辛","半夏、陈皮","石膏、黄芩","知母、川贝母"],"a":1,"e":"干姜辛热温肺化饮，细辛辛温散寒化饮，甘草益气和中、调和药性，三药合用温肺散寒、化饮止咳，如苓甘五味姜辛汤，为寒痰停饮、咳嗽清稀痰之常用配伍。麻黄、杏仁宣肺散寒，主风寒咳嗽；半夏、陈皮燥湿理气，治湿痰；石膏、黄芩清肺热；知母、川贝润燥止咳"},{"q":"脾胃虚弱服药期间应少服哪种食物","o":["腥膻食物","盐、碱过多","辛热助阳","动物内脏","寒冷固硬"],"a":4,"e":"脾胃虚弱者运化力弱，寒冷固硬之物不易消化，易伤脾阳、碍胃气，故服药期间应少食，以免加重脘腹胀满、便溏。腥膻食物多动风发疮；盐、碱过多易伤阴助水肿；辛热助阳助火伤阴；动物内脏滋腻难化，各有所忌，但与脾胃虚弱直接相悖者首推寒冷固硬"},{"q":"水肿患者服药期间应少服哪种食物","o":["腥膻食物","盐、碱过多","辛热助阳","动物内脏","寒冷固硬"],"a":1,"e":"水肿患者水液代谢失常，盐、碱过多摄入则钠水潴留，加重水肿，故服药期间须少食，即忌盐之谓。腥膻食物易碍胃生湿；辛热助阳耗伤阴液；动物内脏滋腻；寒冷固硬伤脾阳，虽皆当慎，但直接导致水钠潴留、加重水肿者以盐碱为甚"},{"q":"均药性寒凉，多用以治疗风湿热痹的药物是","o":["独活、川乌、威灵仙、防己","防己、络石藤、蕲蛇、穿山龙","川乌、独活、威灵仙、油松节","防己、络石藤、豨莶草、桑枝","蚕沙、伸筋草、秦艽、桑枝"],"a":3,"e":"防己苦寒，祛风止痛、利水消肿；络石藤微寒，祛风通络、凉血消肿；豨莶草苦寒，祛风湿、利关节、解毒；桑枝微苦平偏凉，祛风湿、利关节。四者均性偏寒凉，善治风湿热痹、关节红肿热痛。川乌、独活、威灵仙、油松节皆温热，宜风寒湿痹；蕲蛇、穿山龙、蚕沙、伸筋草、秦艽等或温或平，不属纯寒凉组"},{"q":"均药性温热，多用以治疗风寒湿痹的药物是","o":["独活、川乌、威灵仙、防己","防己、络石藤、蕲蛇、穿山龙","川乌、独活、威灵仙、油松节","防己、络石藤、豨莶草、桑枝","蚕沙、伸筋草、秦艽、桑枝"],"a":2,"e":"川乌辛热，祛风除湿、温经止痛；独活辛苦微温，祛风除湿、通痹止痛，善治下半身痹痛；威灵仙辛温，祛风湿、通经络、止痛；油松节苦温，祛风除湿、通络止痛。四者均性温热，善治风寒湿痹、寒凝疼痛。防己、络石藤、豨莶草、桑枝性寒凉，主风湿热痹；秦艽、蚕沙等性平或凉，不属温热之列"},{"q":"治疗外感风寒夹湿表证，宜选用","o":["草豆蔻","草果","苍术","豆蔻","厚朴"],"a":2,"e":"苍术辛苦温，归脾、胃、肝经，功能燥湿健脾、祛风散寒、明目，辛温发散、苦温燥湿，善治外感风寒夹湿之表证，见恶寒发热、头身困重、无汗。草豆蔻、草果燥湿温中，偏治寒湿中阻；豆蔻化湿行气、温中止呕；厚朴燥湿消痰、下气除满，皆非解表之品"},{"q":"治疗夜盲，眼目昏涩，宜选用","o":["草豆蔻","草果","苍术","豆蔻","厚朴"],"a":2,"e":"苍术辛苦温，功能燥湿健脾、祛风散寒、明目，富含维生素甲样物质，善治夜盲症及眼目昏涩，故有明目之功。草豆蔻、草果温中燥湿，无明目之效；豆蔻化湿行气；厚朴下气除满。治夜盲、眼目昏涩以苍术为要，余药均无此长"},{"q":"为了缓和大黄的泻下作用，宜采用何种制法","o":["润","煨","炙","淬","蒸制"],"a":4,"e":"大黄生用泻下力强，含较多结合型蒽醌；经蒸制后部分结合蒽醌水解，泻下作用缓和，且能活血祛瘀、清热解毒，适用于老年、体虚或需缓泻者。润制多用于质地坚硬或需软化者；煨制多去油或缓和对胃刺激；炙一般指蜜炙、酒炙等，增强补益或活血；淬多用于矿物药，均非缓和大黄泻下的常法"},{"q":"为了增强黄芪、甘草的补中益气作用，宜采用何种制法","o":["润","煨","炙","淬","蒸制"],"a":2,"e":"黄芪、甘草生用偏于清热、固表或解毒，蜜炙后甘温之性增强，能补中益气、健脾和胃，故增强补中益气作用宜炙用。润法多用于软化药材；煨法去油减刺激性；淬法用于矿物、贝壳类；蒸制多改变药性或缓和药性（如大黄），均非增强补气之常规炮制"},{"q":"具有降的作用趋向的药物能够治疗","o":["病势表现为向上，如呕吐、喘咳、呃逆","病势表现为向下，如泄利、脱肛、子宫下垂","病势表现为向外，如自汗、盗汗","病势表现为向内，如表证不解","病势表现为向内，如表证不解；又有病势表现为向下，如泄利"],"a":0,"e":"升降浮沉中，降性药物作用趋向向下、向里，能降逆、止呕、平喘、泻下，故可治病势向上之呕吐、喘咳、呃逆等症。病势向下之泄利、脱肛、子宫下垂当用升提之品；自汗、盗汗属卫表不固，当固表；表证不解当发散；寒热错杂、表里同病当权衡升降，均与降法相反"},{"q":"甘味药作用是","o":["发汗、解表、行气、活血","补中益气、缓急止痛、调和药性、和中","收敛固涩","软坚散结、泻下通便","渗湿利水、利尿通淋"],"a":1,"e":"甘味药能补、能和、能缓，功能补中益气、缓急止痛、调和药性、和中，适用于虚证、拘急疼痛及药性调和。发汗、解表、行气、活血为辛味之用；收敛固涩属酸味；软坚散结、泻下通便属咸味；渗湿利水、利尿通淋多为淡味，非甘味所主"},{"q":"辛味药作用是","o":["发汗、解表、行气、活血","补中益气、缓急止痛、调和药性、和中","收敛固涩","软坚散结、泻下通便","渗湿利水、利尿通淋"],"a":0,"e":"辛味药能散、能行，功能发汗、解表、行气、活血，适用于表证、气滞、血瘀等证。补中益气、缓急止痛、调和药性、和中为甘味之用；收敛固涩属酸味；软坚散结、泻下通便属咸味；渗湿利水属淡味。辛散行气血，与甘补酸收咸软各异"},{"q":"治血热出血，宜选用的药物是","o":["夏枯草","决明子","芦根","栀子","密蒙花"],"a":3,"e":"栀子苦寒，归心、肺、三焦经，功能泻火除烦、清热利湿、凉血解毒，炒炭后凉血止血，可治血热妄行之吐血、衄血、尿血等。夏枯草清肝明目、散结；决明子清肝明目、润肠；芦根清热生津、除烦止呕、利尿；密蒙花清热养肝、明目退翳，均无凉血止血之功"},{"q":"治胃热呕哕，宜选用的药物是","o":["夏枯草","决明子","芦根","栀子","密蒙花"],"a":2,"e":"芦根甘寒，归肺、胃经，功能清热生津、除烦、止呕、利尿，善清胃热而降逆止呕，治胃热呕哕、呃逆及热病口渴。夏枯草清肝火；决明子清肝润肠；栀子泻火除烦、凉血止血，无止呕之能；密蒙花清肝明目。清胃止呕为芦根所长"},{"q":"海藻、昆布的共同功效是","o":["润肺化气，化痰止咳","软坚散结，制酸止痛","消痰软坚，利水消肿","止咳平喘，润肠通便","清热化痰，清心定惊"],"a":2,"e":"海藻、昆布均咸寒，归肝、胃、肾经，功能消痰软坚、利水消肿，善治瘰疬、瘿瘤、噎膈及水肿脚气，咸能软坚散结。润肺化痰止咳多属川贝、浙贝；制酸止痛为海蛤壳、瓦楞子所主；止咳平喘、润肠通便属杏仁、紫苏子；清热化痰、清心定惊属天竺黄，均非二药共有"},{"q":"海蛤壳、瓦楞子的共同功效是","o":["润肺化气，化痰止咳","软坚散结，制酸止痛","消痰软坚，利水消肿","止咳平喘，润肠通便","清热化痰，清心定惊"],"a":1,"e":"海蛤壳、瓦楞子均咸寒，功能清热化痰、软坚散结，瓦楞子兼能制酸止痛，海蛤壳亦有利尿、制酸之效，二者共同功效为软坚散结、制酸止痛，善治瘿瘤瘰疬、胃痛泛酸。消痰软坚、利水消肿为海藻、昆布所主；润肺止咳、润肠通便、清心定惊各属他药"},{"q":"依据中药药性理论，辛味所示的作用是","o":["收敛固涩","发散、行气","补虚、缓急","坚阴、通泄","软坚散结、泻下通便"],"a":1,"e":"依据药性理论，辛味能散、能行，所示作用为发散、行气、行血，治表证、气滞血瘀。收敛固涩属酸味；补虚、缓急属甘味；坚阴、通泄属苦味（黄柏、大黄之类）；软坚散结、泻下通便属咸味。五味各有所主，发散行气为辛味专属"},{"q":"依据中药药性理论，苦味所示的作用是","o":["收敛固涩","发散、行气","补虚、缓急","坚阴、通泄","软坚散结、泻下通便"],"a":3,"e":"苦味能泄、能燥、能坚，所示作用为通泄、降泄、清泄及坚阴，如大黄通泄、杏仁降泄、黄连清泄、黄柏知母坚阴。收敛固涩属酸味；发散、行气属辛味；补虚、缓急属甘味；软坚散结、泻下通便属咸味。苦味坚阴通泄之说源于《素问》，与他味判然有别"},{"q":"治湿热泻痢、里急后重，最宜黄连配伍","o":["香附","木香","佛手","乌药","枳实"],"a":1,"e":"黄连苦寒，清热燥湿、泻火解毒，善清肠胃湿热而止痢；木香辛苦温，行气止痛、健脾消食，善行大肠气滞。二药相伍，清热燥湿与行气止痛并用，治湿热泻痢、里急后重最为适宜，如香连丸。香附疏肝理气、调经止痛；佛手疏肝理气、和胃化痰；乌药行气止痛、温肾散寒；枳实破气消积，均非治痢要配"},{"q":"治痰湿阻闭、胸阳不振之胸痹疼痛，最宜薤白配伍","o":["香附","木香","佛手","乌药","枳实"],"a":4,"e":"薤白辛温，通阳散结、行气导滞，为治胸痹要药；枳实苦辛微寒，破气消积、化痰散痞。二药合用，通阳散结、行气消痰，善治痰湿阻闭、胸阳不振之胸痹疼痛、胸闷痞满，如枳实薤白桂枝汤。香附疏肝调经；木香行气止痛，主肠胃气滞；佛手疏肝和胃；乌药温肾行气，均非通阳治胸痹之配"},{"q":"气虚血少之证多用何类药味治疗","o":["咸","甘","酸","辛","苦"],"a":1,"e":"甘味能补、能和、能缓，具补虚、和中、缓急之功，气虚血少之证多用甘味药治疗，如黄芪、当归、熟地、阿胶之类。咸味软坚散结、泻下；酸味收敛固涩；辛味发散行气活血，久用耗气伤血；苦味清热燥湿、通泄，均非补虚养血所选"},{"q":"洋金花的功效是","o":["泻肺平喘，利水消肿","清肺止咳，降逆止呕","清宣肺气，润肠通便","敛肺平喘，止带缩尿","平喘止咳，解痉，定痛"],"a":4,"e":"洋金花辛温，有大毒，归肺、肝经，功能平喘止咳、解痉、定痛，善治哮喘咳嗽、小儿慢惊、风湿痹痛及外科麻醉，为麻醉要药。泻肺平喘、利水消肿为桑白皮、葶苈子；清肺止咳、降逆止呕为枇杷叶；清宣肺气、润肠通便为马兜铃类；敛肺平喘、止带缩尿为白果，均与洋金花不同"},{"q":"暑月外感风寒，内伤生冷，见恶寒发热、头痛脘闷、呕恶吐泻，治宜首选","o":["广藿香","佩兰","苍术","草果","豆蔻"],"a":0,"e":"广藿香辛微温，归脾、胃、肺经，功能芳香化浊、和中止呕、发表解暑，善治暑月外感风寒、内伤生冷之恶寒发热、头痛脘闷、呕恶吐泻，如藿香正气散。佩兰化湿解暑，主脾瘅口甜多涎；苍术燥湿健脾、祛风散寒；草果燥湿温中、截疟；豆蔻化湿行气、温中止呕，均无解表和中兼备之长"},{"q":"脾经湿热，口中甜腻、多涎、口臭，治宜首选","o":["广藿香","佩兰","苍术","草果","豆蔻"],"a":1,"e":"佩兰辛平，归脾、胃、肺经，功能芳香化湿、醒脾开胃、发表解暑，善治脾经湿热、口中甜腻、多涎、口臭之脾瘅，以及暑湿表证。广藿香和中止呕、发表解暑，主呕吐泄泻；苍术燥湿健脾；草果温中燥湿截疟；豆蔻化湿行气温中。治口甜多涎以佩兰为专药"},{"q":"具有泻火平肝功效的药物是","o":["野菊花","蒲公英","金银花","紫花地丁","白头翁"],"a":0,"e":"野菊花苦辛微寒，归肺、肝经，功能清热解毒、泻火平肝，善治疮痈肿毒、咽喉肿痛、目赤肿痛及肝火上炎之头晕目眩，泻火平肝之力较为突出。蒲公英清热解毒、消痈散结、利尿通淋；金银花清热解毒、疏散风热；紫花地丁清热解毒、凉血消肿；白头翁清热解毒、凉血止痢，均无平肝之效"},{"q":"具有利尿通淋功效的药物是","o":["野菊花","蒲公英","金银花","紫花地丁","白头翁"],"a":1,"e":"蒲公英苦甘寒，归肝、胃经，功能清热解毒、消痈散结、利湿通淋，善治乳痈、疮毒、热淋涩痛，兼能利湿通淋。野菊花清热解毒、泻火平肝；金银花清热解毒、疏散风热；紫花地丁清热解毒、凉血消肿；白头翁凉血止痢。利尿通淋为蒲公英所兼具"},{"q":"白术治疗脾虚气滞、脘腹痞满，常配伍","o":["当归","砂仁","枳实","山楂","西洋参"],"a":2,"e":"白术苦甘温，健脾益气、燥湿利水、止汗安胎；枳实苦辛微寒，破气消积、化痰散痞。二药一补一消，一温一寒，相伍为用，健脾与行气消痞并举，治脾虚气滞、脘腹痞满、食少不化，如枳术丸。当归补血活血；砂仁化湿行气安胎；山楂消食化积；西洋参补气养阴，均非消痞除满之配"},{"q":"白术治疗脾虚所致的胎动不安，常配伍","o":["当归","砂仁","枳实","山楂","西洋参"],"a":1,"e":"白术健脾益气、燥湿利水、安胎；砂仁化湿行气、温中止呕、安胎。二药相伍，健脾与理气安胎并用，善治脾虚气滞之胎动不安、妊娠恶阻、腹胀食少。当归补血活血调经；枳实破气消积，虚证慎用；山楂消食化积；西洋参补气养阴，无安胎止呕之效"},{"q":"治疗肾阴虚证，宜首选","o":["石斛","百合","北沙参","南沙参","明党参"],"a":0,"e":"石斛甘微寒，归胃、肾经，功能益胃生津、滋阴清热，善滋肾阴、清虚热，治肾阴虚证之腰膝酸软、骨蒸潮热、盗汗遗精，以及胃阴不足、热病伤津。百合养阴润肺、清心安神；北沙参、南沙参养阴清肺、益胃生津，偏于肺胃；明党参润肺化痰、养阴和胃，补肾之力皆不及石斛"},{"q":"功能健脾、润肺、益肾的药物是","o":["黄精","石斛","天冬","枸杞子","墨旱莲"],"a":0,"e":"黄精甘平，归脾、肺、肾经，功能补气养阴、健脾、润肺、益肾，一药而三脏并补，善治脾胃虚弱、肺虚燥咳、肾虚精亏、腰膝酸软、须发早白。石斛益胃生津、滋阴清热；天冬养阴润燥、清肺生津；枸杞子滋补肝肾、益精明目；墨旱莲滋补肝肾、凉血止血，均不兼健脾润肺益肾三者"},{"q":"功能滋补肝肾、凉血止血的药物是","o":["黄精","石斛","天冬","枸杞子","墨旱莲"],"a":4,"e":"墨旱莲甘酸寒，归肝、肾经，功能滋补肝肾、凉血止血，善治肝肾阴虚之腰膝酸软、头晕目眩、须发早白，以及阴虚血热之吐血、衄血、尿血、崩漏。黄精补气养阴、健脾润肺益肾；石斛益胃滋阴清热；天冬养阴润燥清肺；枸杞子滋补肝肾、明目，均无凉血止血之功"},{"q":"具有平肝潜阳，镇惊安神功效的药物是","o":["琥珀","朱砂","磁石","酸枣仁","夜交藤"],"a":2,"e":"磁石咸寒，归肝、心、肾经，功能镇惊安神、平肝潜阳、聪耳明目、纳气平喘，善治心神不宁、惊悸失眠及肝阳上亢之眩晕，为平肝潜阳、镇惊安神之品。琥珀镇惊安神、活血散瘀、利尿通淋；朱砂清心镇惊、安神解毒，无平肝之功；酸枣仁养心益肝、安神敛汗；夜交藤养血安神、祛风通络"},{"q":"既治目赤翳障，又治皮肤湿疹湿疮的药物是","o":["滑石","朱砂","硼砂","寒水石","炉甘石"],"a":4,"e":"炉甘石甘平，归肝、胃经，功能解毒明目退翳、收湿止痒敛疮，为眼科外用要药，治目赤翳障、烂弦风眼，亦治皮肤湿疹、湿疮、溃疡不敛。滑石利尿通淋、清热解暑，外用祛湿敛疮；朱砂镇心安神、清热解毒；硼砂清热解毒、清肺化痰；寒水石清热泻火，均不主治目赤翳障兼湿疹湿疮"},{"q":"既治目赤翳障，又治痰热咳嗽病证的药物是","o":["滑石","朱砂","硼砂","寒水石","炉甘石"],"a":2,"e":"硼砂甘咸凉，归肺、胃经，功能清热解毒、清肺化痰，外用清热解毒、消肿防腐，善治咽喉肿痛、口舌生疮、目赤翳障，内服可治痰热咳嗽。滑石利尿通淋、解暑；朱砂镇惊安神；寒水石清热泻火；炉甘石明目退翳、收湿敛疮，治湿疹湿疮，均无清肺化痰止咳之能"},{"q":"属于相恶关系的是","o":["药物配伍时能产生协同作用而增进疗效","药物配伍时能互相拮抗而抵消、削弱原有功效","药物配伍时能减轻或消除原有毒副作用","药物配伍时能产生或增强毒副作用","药物配伍时既能产生协同作用又能减轻毒副作用"],"a":1,"e":"相恶指两药合用，一药能拮抗另一药而抵消、削弱其原有功效，如人参恶莱菔子、生姜恶黄芩，属配伍禁忌之一。协同增进疗效为相须、相使；减轻消除毒副作用为相杀；产生或增强毒副作用为相反；既协同又减毒者非七情常规配伍，与相恶之拮抗减效判然不同"},{"q":"属于相反关系的是","o":["药物配伍时能产生协同作用而增进疗效","药物配伍时能互相拮抗而抵消、削弱原有功效","药物配伍时能减轻或消除原有毒副作用","药物配伍时能产生或增强毒副作用","药物配伍时既能产生协同作用又能减轻毒副作用"],"a":3,"e":"相反指两药合用能产生或增强毒副作用，如乌头反半夏、甘草反甘遂、藜芦反人参，属十八反配伍禁忌。互相拮抗、削弱功效为相恶；减轻消除毒性为相杀；协同增进疗效为相须、相使；既协同又减毒之说不合相反定义。相反重在增毒，危害最烈"},{"q":"蒲公英既能清热解毒，又能","o":["疏散风热","凉血消斑","泻火定惊","利尿通淋","清热燥湿"],"a":3,"e":"蒲公英苦甘寒，归肝、胃经，功能清热解毒、消痈散结、利湿通淋，除清热解毒外尚能利尿通淋，治热淋涩痛、黄疸，尤善治乳痈。疏散风热属薄荷、牛蒡子；凉血消斑属牡丹皮、紫草；泻火定惊属熊胆、牛黄；清热燥湿属黄连、黄芩，皆非蒲公英之功"},{"q":"善清肺热的药物是","o":["龙胆","黄芩","黄连","黄柏","苦参"],"a":1,"e":"黄芩苦寒，归肺、胆、脾、大肠、小肠经，功能清热燥湿、泻火解毒、止血、安胎，尤善清上焦肺热，治肺热咳嗽、痰黄黏稠，故为清肺热首选。龙胆善泻肝胆实火；黄连清心胃实热；黄柏清下焦虚热、燥湿；苦参清热燥湿、杀虫利尿，归经与所清之热各有侧重"},{"q":"善泻肝胆实火的药物是","o":["龙胆","黄芩","黄连","黄柏","苦参"],"a":0,"e":"龙胆苦寒，归肝、胆经，功能清热燥湿、泻肝胆火，善治肝胆实火上炎之头痛目赤、胁痛口苦、惊风抽搐，以及湿热下注之阴肿阴痒、带下。黄芩清肺热；黄连清心胃实热；黄柏清下焦虚火、燥湿；苦参清热燥湿、杀虫，均无专泻肝胆实火之长"},{"q":"善清胃热，用治牙龈肿痛的药物是","o":["连翘","鱼腥草","熊胆粉","金银花","山豆根"],"a":4,"e":"山豆根苦寒，归肺、胃经，功能清热解毒、利咽消肿，善清胃火，治胃热上攻之牙龈肿痛、口舌生疮，以及热毒咽喉肿痛。连翘清热解毒、消肿散结、疏散风热；鱼腥草清热解毒、消痈排脓、利尿通淋；熊胆粉清热解毒、明目止惊；金银花清热解毒、疏散风热，均无专清胃热治牙痛之能"},{"q":"苍术善治","o":["食积胀满或便秘，咳喘痰多","暑湿证，湿浊中阻之呕吐","妊娠恶阻，气滞胎动不安","风寒湿痹，表证夹湿","水肿，心悸，失眠"],"a":3,"e":"苍术辛苦温，功能燥湿健脾、祛风散寒、明目，善治风寒湿痹、表证夹湿，见肢体关节重痛、头身困重、苔白腻。食积胀满、咳喘痰多为厚朴所主；暑湿呕吐为藿香、佩兰所主；妊娠恶阻、气滞胎动不安为砂仁、紫苏所主；水肿、心悸、失眠多属茯苓、泽泻等，非苍术主治"},{"q":"厚朴善治","o":["食积胀满或便秘，咳喘痰多","暑湿证，湿浊中阻之呕吐","妊娠恶阻，气滞胎动不安","风寒湿痹，表证夹湿","水肿，心悸，失眠"],"a":0,"e":"厚朴苦辛温，归脾、胃、肺、大肠经，功能燥湿消痰、下气除满，善治食积气滞、腹胀便秘、痰饮咳喘，为消胀除满要药。风寒湿痹、表证夹湿为苍术所主；暑湿呕吐为藿香、佩兰所主；妊娠恶阻、气滞胎动不安为砂仁所主；水肿、心悸、失眠属茯苓、泽泻类，均非厚朴所长"},{"q":"属相须配伍的是","o":["石膏配知母","当归配桂枝","乌头配半夏","干姜配细辛","黄芪配茯苓"],"a":0,"e":"相须指性能功效相似的药物配合应用，可增强原有疗效。石膏辛甘大寒，清热泻火、除烦止渴；知母苦甘寒，清热泻火、滋阴润燥，二药相须，清热泻火之力倍增，如白虎汤。当归配桂枝养血温通；乌头配半夏属相反；干姜配细辛温肺化饮；黄芪配茯苓为相使，均非相须"},{"q":"属相使配伍的是","o":["石膏配知母","当归配桂枝","乌头配半夏","干姜配细辛","黄芪配茯苓"],"a":4,"e":"相使指以一药为主、另一药为辅，辅药提高主药功效。黄芪甘温，补气升阳、利水消肿为主；茯苓甘淡平，健脾渗湿为辅，助黄芪补气利水，故黄芪配茯苓属相使。石膏配知母为相须；当归配桂枝养血温通；乌头配半夏为相反；干姜配细辛温肺化饮属相须，均非相使"},{"q":"金钱草除利湿退黄外，还能","o":["通经下乳","通淋排石","疏肝止痛","杀虫止痒","活血化瘀"],"a":1,"e":"金钱草甘咸微寒，归肝、胆、肾、膀胱经，功能利湿退黄、利尿通淋、解毒消肿，善治湿热黄疸、石淋热淋，为排石要药，故除利湿退黄外还能通淋排石。通经下乳属王不留行、穿山甲；疏肝止痛属柴胡、延胡索；杀虫止痒属蛇床子、苦参；活血化瘀属虎杖、丹参，均非金钱草所主"},{"q":"虎杖除利胆退黄外，还能","o":["通经下乳","通淋排石","疏肝止痛","杀虫止痒","活血化瘀"],"a":4,"e":"虎杖苦寒，归肝、胆、肺经，功能利湿退黄、清热解毒、散瘀止痛、化痰止咳，除利胆退黄外还能活血散瘀止痛，治经闭、痛经、跌打损伤、痈肿疮毒。通经下乳属王不留行；通淋排石属金钱草；疏肝止痛属柴胡、延胡索；杀虫止痒属蛇床子、苦参，均非虎杖之功"},{"q":"骨碎补的功效是","o":["消风祛斑","通络止痛","散结消肿","生肌敛疮","消食化积"],"a":0,"e":"骨碎补苦温，归肝、肾经，功能疗伤止痛、补肾强骨，外用消风祛斑，治跌打损伤、骨折、肾虚腰痛久泻，外治斑秃、白癜风，故消风祛斑为其外用之功。通络止痛属马钱子、威灵仙；散结消肿属马钱子、山慈菇；生肌敛疮属血竭、炉甘石；消食化积属山楂、鸡内金，均与骨碎补不同"},{"q":"血竭的功效是","o":["消风祛斑","通络止痛","散结消肿","生肌敛疮","消食化积"],"a":3,"e":"血竭甘咸平，归心、肝经，功能活血定痛、化瘀止血、敛疮生肌，为伤科要药，治跌打损伤、瘀血肿痛、外伤出血及疮疡不敛，故能生肌敛疮。消风祛斑属骨碎补外用；通络止痛属马钱子；散结消肿属马钱子、山慈菇；消食化积属山楂、鸡内金，均非血竭所主"},{"q":"赭石的主治病证是","o":["阳亢眩晕，心悸失眠","阳亢眩晕，目赤目昏","阳亢眩晕，吐血衄血","阳亢眩晕，湿疹湿疮","阳亢眩晕，肝热急惊"],"a":2,"e":"赭石苦寒，归肝、心经，功能平肝潜阳、重镇降逆、凉血止血，善治肝阳上亢之眩晕耳鸣，以及血热妄行之吐血、衄血、崩漏，故主治为阳亢眩晕兼吐血衄血。心悸失眠多属朱砂、酸枣仁；目赤目昏属夏枯草、石决明；湿疹湿疮属炉甘石、苦参；肝热急惊属羚羊角、牛黄，均非赭石所主"},{"q":"矿物、贝壳类药物，因其有效成分难于煎出，入煎剂时宜","o":["先煎","后下","烊化","包煎","另煎"],"a":0,"e":"矿物、贝壳类药物如石膏、龙骨、牡蛎、磁石，质地坚硬，有效成分难溶于水，入汤剂宜先煎，久煎使有效成分充分溶出。后下用于薄荷、砂仁等芳香易挥发或大黄等久煎失效之品；烊化用于阿胶、鹿角胶等胶类；包煎用于旋覆花、车前子等易致药液浑浊或刺激咽喉者；另煎用于人参、西洋参等贵重药"},{"q":"有效成分煎煮时容易挥发或破坏的药物入煎剂时宜","o":["先煎","后下","烊化","包煎","另煎"],"a":1,"e":"有效成分易挥发或被久煎破坏的药物入煎宜后下，如薄荷、砂仁、豆蔻含挥发油，大黄久煎则泻下力减弱，均在余药煎好前短时间下锅。先煎用于矿物贝壳类；烊化用于胶类；包煎用于细小种子、绒毛类；另煎用于贵重药材，均非防挥发破坏之法"},{"q":"蛇床子能够治疗的病证是","o":["虚喘冷哮","虚寒便秘","虫蛇咬伤，疟疾","湿疹，肾阳虚证","牙痛，风湿痹痛"],"a":3,"e":"蛇床子辛苦温，有小毒，归肾经，功能燥湿祛风、杀虫止痒、温肾壮阳，外用治阴部湿疹、湿疮、疥癣瘙痒，内服治肾阳虚之阳痿、不孕，故可治湿疹与肾阳虚证。虚喘冷哮多属蛤蚧、沉香；虚寒便秘属肉苁蓉、锁阳；虫蛇咬伤、疟疾属雄黄、青蒿；牙痛、风湿痹痛属细辛、独活，非蛇床子所主"},{"q":"雄黄能够治疗的病证是","o":["虚喘冷哮","虚寒便秘","虫蛇咬伤，疟疾","湿疹，肾阳虚证","牙痛，风湿痹痛"],"a":2,"e":"雄黄辛温，有大毒，归肝、大肠经，功能解毒、杀虫、燥湿祛痰、截疟，善治痈肿疔疮、蛇虫咬伤、疟疾、疥癣及虫积腹痛。虚喘冷哮属蛤蚧、沉香；虚寒便秘属肉苁蓉；湿疹、肾阳虚证属蛇床子；牙痛、风湿痹痛属细辛、独活，均非雄黄主治"},{"q":"有止呕、除烦功效的药物是","o":["决明子","知母","芦根","密蒙花","天花粉"],"a":2,"e":"芦根甘寒，归肺、胃经，功能清热生津、除烦、止呕、利尿，善清胃热而止呕、除烦，治胃热呕哕、热病烦渴。决明子清肝明目、润肠；知母清热泻火、滋阴润燥，无止呕之能；密蒙花清肝明目；天花粉清热生津、消肿排脓，均无除烦止呕之效"},{"q":"有消肿排脓功效的药物是","o":["决明子","知母","芦根","密蒙花","天花粉"],"a":4,"e":"天花粉甘微苦寒，归肺、胃经，功能清热生津、消肿排脓，善治热病烦渴、消渴及疮痈肿毒、跌打损伤，消肿排脓为其所长。决明子清肝明目、润肠；知母滋阴降火；芦根清热生津、除烦止呕、利尿；密蒙花清肝明目，均无消肿排脓之功"},{"q":"功能降气化痰，又能降逆止呕的药物是","o":["芥子","白前","前胡","紫苏子","旋覆花"],"a":4,"e":"旋覆花苦辛咸微温，归肺、胃经，功能降气化痰、降逆止呕、行水消肿，善治痰饮蓄结、咳喘痰多及胃气上逆之呕吐噫气，如旋覆代赭汤。芥子温肺化痰、利气散结；白前降气化痰止咳，无止呕之功；前胡降气化痰、疏散风热；紫苏子降气化痰、润肠通便，皆不兼降逆止呕"},{"q":"既能降气化痰，又能疏散风热的药物是","o":["芥子","白前","前胡","紫苏子","旋覆花"],"a":2,"e":"前胡苦辛微寒，归肺经，功能降气化痰、疏散风热，善治风热咳嗽、痰多气逆及外感风热表证，故既能降气化痰又能疏散风热。芥子辛温，温肺化痰、利气散结；白前微温，降气化痰止咳，无疏散风热之能；紫苏子润肠通便；旋覆花降逆止呕，均无疏风清热之效"},{"q":"能反映药物影响人体阴阳盛衰的性能是","o":["四气","五味","归经","升降浮沉","毒性"],"a":0,"e":"四气（寒、热、温、凉）反映药物对人体阴阳盛衰、寒热变化的作用倾向：寒凉药能抑制阳盛、清热，温热药能扶助阳气、祛寒，故能反映阴阳盛衰。五味示功能之补泻散收；归经示作用部位；升降浮沉示作用趋向；毒性示安全程度，均不直接反映阴阳盛衰"},{"q":"能反映药物影响人体寒热变化的性能是","o":["四气","五味","归经","升降浮沉","毒性"],"a":0,"e":"四气即寒、热、温、凉四种药性，直接反映药物影响人体寒热变化的性能：寒凉药清热，温热药散寒，是谓寒者热之、热者寒之。五味示发散、补缓、收敛、坚软等作用；归经定位脏腑经络；升降浮沉示趋向；毒性示毒副作用，皆非寒热变化之指标"},{"q":"具有升的作用趋向的药物能够治疗","o":["病势表现为向上，如呕吐、喘咳、呃逆","病势表现为向下，如泄利、脱肛、子宫下垂","病势表现为向外，如自汗、盗汗","病势表现为向内，如表证不解","病势表现为向内，如表证不解；又有病势表现为向下，如泄利"],"a":1,"e":"升性药物作用趋向向上、向外，能升阳举陷、发表散邪，故可治病势向下之泄利、脱肛、子宫下垂等中气下陷之证，如补中益气汤。病势向上之呕吐、喘咳、呃逆当用降逆药；自汗、盗汗当固表；表证不解当发散；升降相因、表里同病当兼顾，均与升提之法有异"},{"q":"木通与萆薢均可治疗","o":["湿热痹证","闭经","血热出血","肺热咳嗽","暑湿泄泻"],"a":0,"e":"木通苦寒，归心、小肠、膀胱经，功能利尿通淋、清心除烦、通经下乳，善清湿热；萆薢苦平，归肾、胃经，功能利湿去浊、祛风除痹，善治膏淋、白浊及风湿痹痛。二者均能祛湿热、通痹，故均可治湿热痹证。闭经多属活血通经药；血热出血属凉血止血药；肺热咳嗽属清肺药；暑湿泄泻属化湿药"},{"q":"车前子与石韦均可治疗","o":["湿热痹证","闭经","血热出血","肺热咳嗽","暑湿泄泻"],"a":3,"e":"车前子甘寒，归肾、肝、肺经，功能利尿通淋、渗湿止泻、明目、祛痰，能清肺化痰止咳；石韦苦微寒，归肺、膀胱经，功能利尿通淋、清肺止咳、凉血止血，善治肺热咳嗽、气喘。二者均归肺经而清肺热，故均可治肺热咳嗽。湿热痹证属防己、萆薢；闭经属活血药；血热出血属凉血药；暑湿泄泻属化湿药"},{"q":"地骨皮能治疗","o":["小儿疳热","疟疾寒热往来","肺热咳嗽","痈疽肿毒","暑邪发热"],"a":2,"e":"地骨皮甘寒，归肺、肝、肾经，功能凉血除蒸、清肺降火，善清肺热而止咳，治肺热咳喘、痰多黄稠，以及阴虚骨蒸潮热。小儿疳热为胡黄连、银柴胡所主；疟疾寒热往来属青蒿、柴胡；痈疽肿毒属清热解毒药；暑邪发热属香薷、滑石，均非地骨皮所主"},{"q":"胡黄连能治疗","o":["小儿疳热","疟疾寒热往来","肺热咳嗽","痈疽肿毒","暑邪发热"],"a":0,"e":"胡黄连苦寒，归肝、胃、大肠经，功能退虚热、清疳热、清湿热，善治小儿疳积发热、阴虚潮热及湿热泻痢、痔肿便血。肺热咳嗽属地骨皮、桑白皮；疟疾寒热往来属青蒿；痈疽肿毒属清热解毒药；暑邪发热属香薷、滑石，均非胡黄连所主"},{"q":"能清肺利咽，止血的药物是","o":["马齿苋","鸦胆子","贯众","马勃","金银花"],"a":3,"e":"马勃辛平，归肺经，功能清热解毒、利咽、止血，善治风热咽痛、音哑及吐血、衄血、外伤出血，故能清肺利咽、止血。马齿苋清热解毒、凉血止血、止痢；鸦胆子清热解毒、燥湿杀虫、截疟；贯众清热解毒、凉血止血、杀虫；金银花清热解毒、疏散风热，均无清肺利咽之效"},{"q":"能清热解毒，凉血止血，止痢的药物是","o":["马齿苋","鸦胆子","贯众","马勃","金银花"],"a":3,"e":"官方答案为马勃，但依据教材，正确答案为马齿苋。马齿苋酸寒，归肝、大肠经，功能清热解毒、凉血止血、止痢，为治热毒血痢之要药，与题述功效完全吻合。马勃虽能清热解毒、止血，但功在利咽，主治咽痛音哑及出血，并无凉血、止痢之效；贯众凉血止血、杀虫而不止痢；鸦胆子燥湿杀虫截疟；金银花清热解毒、疏散风热"},{"q":"惊风抽搐，破伤风，首选的药物是","o":["桑叶","蝉蜕","葛根","升麻","柴胡"],"a":1,"e":"蝉蜕甘寒，归肺、肝经，功能疏散风热、利咽开音、透疹止痒、明目退翳、息风止痉，善治惊风抽搐、破伤风、小儿夜啼及风热咽痛、麻疹不透。桑叶疏散风热、清肺润燥、清肝明目；葛根解肌退热、升阳止泻、生津；升麻发表透疹、清热解毒、升阳举陷；柴胡疏散退热、疏肝解郁、升阳举陷，均无息风止痉之力"},{"q":"治疗热毒咽痛，甘草常配伍","o":["桔梗","白芍","党参","小麦","黑豆"],"a":0,"e":"桔梗苦辛平，归肺经，功能宣肺、利咽、祛痰、排脓；甘草清热解毒、祛痰止咳、调和诸药。二药相伍，即桔梗汤，清热利咽、祛痰止咳，善治热毒咽痛、肺痈吐脓。白芍配甘草缓急止痛；党参配甘草补中益气；小麦配甘草、大枣养心安神；黑豆配甘草解毒，均非治咽痛之配"},{"q":"治疗脘腹及四肢挛急作痛，甘草常配伍","o":["桔梗","白芍","党参","小麦","黑豆"],"a":1,"e":"白芍养血敛阴、柔肝止痛、平抑肝阳；甘草益气和中、缓急止痛。二药相须，酸甘化阴、缓急止痛，即芍药甘草汤，善治脘腹及四肢挛急作痛、腓肠肌痉挛。桔梗配甘草利咽祛痰；党参配甘草补气和中；小麦配甘草养心安神；黑豆配甘草解毒，均无缓急止痛之效"},{"q":"赭石的功效是","o":["既能平抑肝阳，又能软坚散结","既能平肝潜阳，又能凉血止血","既能息风止痉，又能收敛固涩","既能平降肝阳，又能疏肝解郁","既能息风止痉，又能清肝明目"],"a":1,"e":"赭石苦寒，归肝、心经，功能平肝潜阳、重镇降逆、凉血止血，故既能平肝潜阳，又能凉血止血，治肝阳眩晕、呕吐呃逆、噫气及吐血衄血、崩漏。软坚散结属牡蛎、海藻；息风止痉、收敛固涩属龙骨、僵蚕类；疏肝解郁属柴胡、香附；清肝明目属石决明、夏枯草，均非赭石之功"},{"q":"蒺藜的功效是","o":["既能平抑肝阳，又能软坚散结","既能平肝潜阳，又能凉血止血","既能息风止痉，又能收敛固涩","既能平降肝阳，又能疏肝解郁","既能息风止痉，又能清肝明目"],"a":3,"e":"蒺藜辛苦平，归肝经，功能平肝解郁、活血祛风、明目、止痒，故能平降肝阳、疏肝解郁，治肝阳上亢之眩晕、肝郁气滞之胁痛及目赤翳障、风疹瘙痒。软坚散结属牡蛎、海藻；凉血止血属赭石、茜草；息风止痉、收敛固涩属龙骨、蜈蚣类；清肝明目属夏枯草、决明子，均非蒺藜所主"},{"q":"麻黄根和浮小麦的共同功效是","o":["益气","止汗","止咳","清肺生津","益胃生津"],"a":1,"e":"麻黄根甘平，归心、肺经，功能固表止汗，为止汗专药，治自汗、盗汗；浮小麦甘凉，归心经，功能固表止汗、益气除热，治自汗盗汗、骨蒸劳热。二者共同功效为止汗。益气为黄芪、党参所主；止咳为杏仁、紫苏子所主；清肺生津为芦根、天花粉；益胃生津为石斛、麦冬，均非二药共性"},{"q":"糯稻根须和石斛的共同功效是","o":["益气","止汗","止咳","清肺生津","益胃生津"],"a":4,"e":"糯稻根须甘平，归肝、胃、肾经，功能固表止汗、益胃生津、退虚热，治自汗盗汗、津伤口渴；石斛甘微寒，归胃、肾经，功能益胃生津、滋阴清热。二者共同功效为益胃生津。止汗虽糯稻根须亦有，但石斛无之；止咳属杏仁类；清肺生津属芦根、天花粉；益气属黄芪、党参，均非共有"},{"q":"宜在含苞待放时采收的药物是","o":["辛夷","蒲黄","瓜蒌","枳实","枸杞"],"a":0,"e":"辛夷为木兰科植物望春花、玉兰等的干燥花蕾，宜在含苞待放时采收，此时挥发油含量高、药效佳，功能发散风寒、通鼻窍，治风寒头痛、鼻塞流涕、鼻渊。蒲黄为花粉，采收花粉；瓜蒌、枸杞采成熟果实；枳实采未成熟幼果，采收时期与辛夷不同"},{"q":"宜采收未成熟幼果的药物是","o":["辛夷","蒲黄","瓜蒌","枳实","枸杞"],"a":3,"e":"枳实为芸香科植物酸橙及其栽培变种的干燥未成熟幼果，性较峻烈，功能破气消积、化痰散痞，治积滞内停、痞满胀痛、泻痢后重。辛夷采花蕾；蒲黄采花粉；瓜蒌、枸杞采成熟果实，均非幼果入药。同一植物成熟果实为枳壳，作用较枳实缓和"},{"q":"治疗阴虚外感，宜首选","o":["龟甲","玉竹","百合","麦冬","北沙参"],"a":1,"e":"玉竹甘微寒，归肺、胃经，功能养阴润燥、生津止渴，质润而不腻，善治阴虚外感、燥邪伤肺之咳嗽咽干，如加减葳蕤汤，故阴虚外感首选玉竹。龟甲滋阴潜阳、益肾强骨；百合养阴润肺、清心安神；麦冬养阴润肺、益胃生津、清心除烦；北沙参养阴清肺、益胃生津，均无解表祛邪之功"},{"q":"治疗肾虚筋骨痿软，宜首选","o":["龟甲","玉竹","百合","麦冬","北沙参"],"a":0,"e":"龟甲咸甘寒，归肝、肾、心经，功能滋阴潜阳、益肾强骨、养血补心、固经止崩，善治肾虚筋骨痿软、腰膝酸软、小儿囟门不合及阴虚阳亢、潮热盗汗。玉竹养阴润燥；百合润肺清心；麦冬养阴生津；北沙参养阴清肺，均无益肾强骨之效"},{"q":"木香、乌药都具有的功效是","o":["降逆止呕","理气调中","行气止痛","温肾纳气","疏肝理气"],"a":2,"e":"木香辛苦温，归脾、胃、大肠、三焦、胆经，功能行气止痛、健脾消食，善行肠胃气滞；乌药辛温，归肺、脾、肾、膀胱经，功能行气止痛、温肾散寒，善行胸腹、下焦气滞。二者共同功效为行气止痛。降逆止呕属半夏、旋覆花；理气调中属陈皮之类；温肾纳气属沉香；疏肝理气属柴胡、香附，均非二者共有"},{"q":"柴胡、升麻与葛根都具有的功效是","o":["清热解毒","发表升阳","透疹利咽","疏肝解郁","解肌退热"],"a":1,"e":"柴胡辛微寒，功能疏散退热、疏肝解郁、升举阳气；升麻辛微寒，功能发表透疹、清热解毒、升举阳气；葛根甘辛凉，功能解肌退热、生津、透疹、升阳止泻。三者均能发表散邪、升举阳气，故共有功效为发表升阳。清热解毒仅升麻具备；透疹利咽为升麻、葛根之类；疏肝解郁仅柴胡；解肌退热仅葛根"},{"q":"薄荷、牛蒡子与蝉蜕都具有的功效是","o":["清热解毒","发表升阳","透疹利咽","疏肝解郁","解肌退热"],"a":2,"e":"薄荷辛凉，功能疏散风热、清利头目、利咽透疹、疏肝行气；牛蒡子辛苦寒，功能疏散风热、宣肺透疹、解毒利咽；蝉蜕甘寒，功能疏散风热、利咽开音、透疹止痒。三者均能疏散风热、透疹利咽。清热解毒仅牛蒡子；发表升阳属柴胡、升麻、葛根；疏肝解郁仅薄荷；解肌退热属葛根，均非共有"},{"q":"善清心胃实热的药物是","o":["龙胆","黄芩","黄连","黄柏","苦参"],"a":2,"e":"黄连苦寒，归心、脾、胃、肝、胆、大肠经，功能清热燥湿、泻火解毒，尤善清心火、胃火，治心烦不眠、胃热呕吐、牙龈肿痛及湿热泻痢。黄芩清肺热；黄柏清下焦虚热、燥湿；龙胆泻肝胆实火；苦参清热燥湿、杀虫利尿，所清之热各有归经，唯黄连主心胃实热"},{"q":"性微寒，能疏散风热的药物是","o":["海藻","前胡","白前","白附子","胖大海"],"a":1,"e":"前胡苦辛微寒，归肺经，功能降气化痰、疏散风热，性微寒而能疏散风热，治风热咳嗽、痰多气逆。海藻咸寒，消痰软坚、利水消肿，无解表之功；白前辛甘微温，降气化痰止咳，性温；白附子辛温有毒，祛风痰、定惊搐；胖大海甘寒，清热润肺、利咽开音、润肠通便，均无疏散风热之效"},{"q":"性微温，能降气祛痰的药物是","o":["海藻","前胡","白前","白附子","胖大海"],"a":2,"e":"白前辛甘微温，归肺经，功能降气化痰止咳，性微温而善降气祛痰，治咳嗽痰多、气逆喘促，尤宜寒痰、湿痰。海藻咸寒软坚；前胡微寒，降气化痰兼疏散风热；白附子辛温有毒，祛风痰定惊；胖大海甘寒，润肺利咽，均无温化寒痰、降气止咳之专功"},{"q":"郁李仁的使用注意是","o":["脾虚便溏，湿痰者禁用","孕妇慎用","哺乳期慎用","不宜与巴豆同用","不宜与丁香同用"],"a":1,"e":"郁李仁辛苦甘平，归脾、大肠、小肠经，功能润肠通便、下气利水，质润多脂，善治肠燥便秘、水肿脚气，因其润下、行气利水，孕妇用之恐动胎气，故孕妇慎用。脾虚便溏、湿痰者禁用为松子仁等滋润药之注意；哺乳期慎用、不宜与巴豆或丁香同用均非郁李仁的规定"},{"q":"松子仁的使用注意是","o":["脾虚便溏，湿痰者禁用","孕妇慎用","哺乳期慎用","不宜与巴豆同用","不宜与丁香同用"],"a":0,"e":"松子仁甘温，归肺、肝、大肠经，功能润肠通便、润肺止咳，富含油脂，滋润性强，脾虚便溏、湿痰内盛者服之更易助湿生痰、加重便溏，故禁用。孕妇慎用为郁李仁之注意；哺乳期慎用非其禁忌；不宜与巴豆、丁香同用属配伍禁忌，均非松子仁使用注意"},{"q":"芦根的药用部位是","o":["根","根茎","花粉","果实","种子"],"a":1,"e":"芦根为禾本科植物芦苇的干燥根茎，药用部位为根茎，功能清热生津、除烦、止呕、利尿。根为天花粉、白薇等药用；花粉为蒲黄之类；果实如瓜蒌、枸杞；种子如杏仁、桃仁。芦苇的地下茎入药，非根、花、果、种子，故芦根药用部位为根茎"},{"q":"天花粉的药用部位是","o":["根","根茎","花粉","果实","种子"],"a":0,"e":"天花粉为葫芦科植物栝楼或双边栝楼的干燥根，药用部位为根，功能清热生津、消肿排脓。根茎如芦根、姜黄；花粉如蒲黄，为花粉入药；果实如瓜蒌，为栝楼成熟果实；种子如栝楼子。天花粉虽名花粉，实为根加工之淀粉，药用部位是根而非花粉"},{"q":"肺热咳嗽，燥热咳嗽，常选用的药物是","o":["桑叶","蝉蜕","蔓荆子","牛蒡子","淡豆豉"],"a":0,"e":"桑叶甘苦寒，归肺、肝经，功能疏散风热、清肺润燥、清肝明目，善治风热感冒、肺热燥咳、痰少咽干及肝阳上亢之目赤昏花，故肺热、燥热咳嗽常选用桑叶。蝉蜕利咽开音、息风止痉；蔓荆子清利头目、祛风止痛，主目赤多泪、风湿痹痛；牛蒡子宣肺透疹、解毒利咽；淡豆豉解表除烦，均非润燥止咳之品"},{"q":"目赤多泪，目暗不明，风湿痹痛，常选用的药物是","o":["桑叶","蝉蜕","蔓荆子","牛蒡子","淡豆豉"],"a":2,"e":"蔓荆子辛苦微寒，归膀胱、肝、胃经，功能疏散风热、清利头目、祛风止痛，善治风热头痛、目赤多泪、目暗不明及风湿痹痛、牙痛。桑叶清肺润燥、清肝明目，主肺热燥咳；蝉蜕利咽透疹、息风止痉；牛蒡子宣肺解毒利咽；淡豆豉解表除烦，均无祛风止痛治痹痛之长"},{"q":"槐花用于止血，常宜","o":["炒炭","醋炙","蜜炙","盐水炙","用生品"],"a":0,"e":"槐花苦微寒，归肝、大肠经，生用清肝泻火、凉血止血，炒炭后寒性减弱，收涩止血之力增强，善治血热妄行之痔血、便血、吐血、衄血，故用于止血宜炒炭。醋炙多引药入肝、增强止痛；蜜炙增强润肺补中；盐水炙引药入肾；生品偏于清热泻火，止血力弱"},{"q":"槐花用于清热泻火时，宜","o":["炒炭","醋炙","蜜炙","盐水炙","用生品"],"a":4,"e":"槐花生品苦微寒，清肝泻火之力较强，善治肝火上炎之头痛目赤、头晕目眩及血热妄行，用于清热泻火时宜生品。炒炭后收涩止血为主，清热之力减；醋炙、蜜炙、盐水炙分别引经或改变药性，均非清热泻火所宜"},{"q":"患者，女，27岁。月经不调，乳房胀痛，胁肋作痛，神疲食少，舌淡苔薄白，脉弦而虚者。首选的药物是","o":["葛根","柴胡","桑叶","牛蒡子","淡豆豉"],"a":1,"e":"患者月经不调、乳房胀痛、胁肋作痛、脉弦，为肝郁气滞；神疲食少、舌淡苔薄白、脉虚，兼脾虚血弱，属肝郁血虚脾弱之证。柴胡辛微寒，归肝、胆经，功能疏肝解郁、升举阳气、退热，善疏肝理气而调经，如逍遥散，故首选柴胡。葛根解肌升阳止泻；桑叶清肺润燥；牛蒡子解毒利咽；淡豆豉解表除烦，均不疏肝调经"},{"q":"患者，男，29岁。表证未解，邪热入里，身热，下利臭秽，肛门有灼热感，舌红苔黄，脉数。首选的药物是","o":["葛根","柴胡","桑叶","牛蒡子","淡豆豉"],"a":0,"e":"患者表证未解、邪热入里，身热、下利臭秽、肛门灼热、舌红苔黄、脉数，为湿热泻痢兼表证发热。葛根甘辛凉，归脾、胃经，功能解肌退热、生津止渴、升阳止泻，既能解表退热，又能升阳止泻，治表证未解、邪热入里之泻痢，如葛根芩连汤，故首选葛根。柴胡疏肝升阳但无止泻之功；桑叶、牛蒡子、淡豆豉均无升阳止泻之效"},{"q":"治丹毒，宜选用的药物是","o":["石膏","寒水石","芦根","决明子","淡竹叶"],"a":1,"e":"寒水石辛咸寒，归心、胃、肾经，功能清热泻火，外用清热消肿，善治热毒疮肿、丹毒、烫伤及口舌生疮，故治丹毒宜选寒水石。石膏清热泻火、除烦止渴，主气分实热；芦根清热生津、止呕利尿；决明子清肝明目；淡竹叶清热除烦、利尿，均无治丹毒之专功"},{"q":"治肺痈吐脓，宜选用的药物是","o":["石膏","寒水石","芦根","决明子","淡竹叶"],"a":2,"e":"芦根甘寒，归肺、胃经，功能清热生津、除烦、止呕、利尿，兼能清肺热、祛痰排脓，善治肺热咳嗽、肺痈吐脓，故肺痈吐脓宜选芦根。石膏清气分实热；寒水石清热泻火，外用消肿；决明子清肝明目；淡竹叶清心利尿，均无清肺排脓之效"},{"q":"患者，女，45岁。心烦失眠，耳鸣耳聋，小便短赤，舌质红苔黄。宜选","o":["朱砂配磁石","朱砂配黄连","朱砂配茯神","朱砂配丹参","朱砂配生甘草"],"a":0,"e":"患者心烦失眠、耳鸣耳聋、小便短赤、舌红苔黄，为心火亢盛、肾阴不足、心肾不交之证。朱砂清心镇惊、安神解毒，磁石咸寒，镇惊安神、平肝潜阳、聪耳明目、纳气平喘，二药相伍，重镇安神、清心滋肾、聪耳，善治心神不宁、耳鸣耳聋、失眠，故宜朱砂配磁石。朱砂配黄连清心泻火；配茯神安神；配丹参活血安神；配生甘草解毒，均无聪耳明目、交通心肾之功"},{"q":"钩藤的功效是","o":["息风定惊，清热平肝，疏风透热","息风止痉，平抑肝阳，祛风通络","息风定惊，清热养肝，祛风通络","平肝息风，养肝明目，疏风透热","平肝息风，养肝明目，祛风通络"],"a":0,"e":"钩藤甘凉，归肝、心包经，功能息风定惊、清热平肝、疏风透热，善治肝风内动、惊痫抽搐、感冒夹惊及肝阳上亢之头痛眩晕，故其功效为息风定惊、清热平肝、疏风透热。息风止痉、平抑肝阳、祛风通络为天麻之功；养肝明目属石决明、枸杞子；收敛固涩属龙骨、牡蛎，均非钩藤所主"},{"q":"天麻的功效是","o":["息风定惊，清热平肝，疏风透热","息风止痉，平抑肝阳，祛风通络","息风定惊，清热养肝，祛风通络","平肝息风，养肝明目，疏风透热","平肝息风，养肝明目，祛风通络"],"a":1,"e":"天麻甘平，归肝经，功能息风止痉、平抑肝阳、祛风通络，善治肝风内动、惊痫抽搐、眩晕头痛及风湿痹痛、肢体麻木，为治眩晕之要药。息风定惊、清热平肝、疏风透热为钩藤之功；养肝明目属石决明、夏枯草；收敛固涩属龙骨、牡蛎，均非天麻所主"},{"q":"属相反配伍的是","o":["黄芪配知母","当归配桂枝","乌头配半夏","干姜配细辛","丁香配郁金"],"a":2,"e":"十八反歌诀半蒌贝蔹及攻乌，乌头反半夏、瓜蒌、贝母、白蔹、白及，故乌头配半夏属相反配伍。丁香配郁金为十九畏丁香莫与郁金见，非相反；黄芪配知母、当归配桂枝、干姜配细辛均无相反或相畏关系，属正常配伍"},{"q":"属“十九畏”内容的是","o":["黄芪配知母","当归配桂枝","乌头配半夏","干姜配细辛","丁香配郁金"],"a":4,"e":"十九畏有丁香莫与郁金见，丁香与郁金相畏，属十九畏内容。乌头配半夏为十八反半蒌贝蔹及攻乌，不在十九畏之列；黄芪配知母、当归配桂枝、干姜配细辛均无相畏关系，不属十九畏"},{"q":"功能退虚热，又可燥湿，用于治疗湿热黄疸的药物是","o":["黄柏","玄参","知母","地骨皮","牡丹皮"],"a":0,"e":"黄柏苦寒，归肾、膀胱、大肠经，功能清热燥湿、泻火除蒸、解毒疗疮，既退虚热治骨蒸潮热，又清热燥湿而疗湿热黄疸。知母退虚热而重在滋阴润燥，无燥湿之功；玄参凉血解毒散结；地骨皮退虚热、清泻肺热；牡丹皮清热凉血、活血散瘀，均不能燥湿治黄疸"},{"q":"功能退虚热，又可解毒，用于治疗瘰疬痰核的药物是","o":["黄柏","玄参","知母","地骨皮","牡丹皮"],"a":1,"e":"玄参甘苦咸寒，功能清热凉血、滋阴降火、解毒散结，可退虚热，并以解毒散结治瘰疬痰核。黄柏重在清热燥湿、泻火除蒸，无散结治瘰疬之力；知母滋阴润燥；地骨皮清虚热、凉血；牡丹皮凉血活血散瘀，均非治瘰疬痰核之品"},{"q":"紫草的功效是","o":["清热凉血，活血散瘀","清热凉血，祛瘀止痛","凉血活血，解毒透疹","凉血止血，泻火解毒","凉血退蒸，清泻肺热"],"a":2,"e":"紫草甘寒，归心、肝经，功能清热凉血、活血、解毒透疹，麻疹紫暗不透者最为适用。清热凉血、活血散瘀为牡丹皮之功；清热凉血、祛瘀止痛属赤芍；凉血止血、泻火解毒属栀子炭；凉血退蒸、清泻肺热属地骨皮，均与紫草解毒透疹之性不符"},{"q":"栀子的功效是","o":["清热凉血，活血散瘀","清热凉血，祛瘀止痛","凉血活血，解毒透疹","凉血止血，泻火解毒","凉血退蒸，清泻肺热"],"a":3,"e":"栀子苦寒，归心、肺、三焦经，生用泻火除烦、清热利湿、凉血解毒，炒炭则凉血止血，兼具泻火解毒之效。清热凉血、活血散瘀属牡丹皮；祛瘀止痛属赤芍；解毒透疹属紫草；凉血退蒸、清泻肺热属地骨皮，皆非栀子功效"},{"q":"青黛的用法是","o":["宜炒炭用","宜另煎","宜入丸散用","只宜外用","宜包煎"],"a":2,"e":"青黛为蓼蓝等加工制成的干燥粉末，咸寒，难溶于水，不入汤剂煎服，宜入丸散或冲服。宜炒炭用多指增强止血或减毒之品；宜另煎多为贵重药如人参、西洋参；只宜外用如升药、炉甘石；宜包煎多为细小种子、花粉及绒毛类药如蒲黄、海金沙，均非青黛用法"},{"q":"熊胆粉的用法是","o":["宜炒炭用","宜另煎","宜入丸散用","只宜外用","宜包煎"],"a":2,"e":"熊胆粉为熊胆汁干燥品，苦寒贵重，遇高温易破坏有效成分，不入汤剂，宜入丸散服用，亦可外用点眼。宜炒炭用非其法；宜另煎虽用于部分贵重药，熊胆多直接入丸散；只宜外用不符，熊胆亦可内服；宜包煎用于细小种子及绒毛类药物，均与熊胆无关"},{"q":"蜈蚣的性味是","o":["咸，寒","辛，平","辛，温","咸、辛，平","咸、辛，温"],"a":2,"e":"蜈蚣辛温有毒，归肝经，功能息风镇痉、攻毒散结、通络止痛，性温燥烈。全蝎则为辛平有毒，甘缓和，故辛平属全蝎；咸寒多为软坚或凉血之品；咸辛平、咸辛温皆非蜈蚣标准性味，蜈蚣以纯辛温有毒为要"},{"q":"全蝎的性味是","o":["咸，寒","辛，平","辛，温","咸、辛，平","咸、辛，温"],"a":1,"e":"全蝎辛平有毒，归肝经，功能息风镇痉、攻毒散结、通络止痛，性较蜈蚣平和。蜈蚣为辛温有毒，温燥之性更强，故辛温属蜈蚣；咸寒为咸寒软坚类药；咸辛平、咸辛温均非全蝎性味，全蝎以辛平有毒为特征"},{"q":"不宜与半夏同用的药物是","o":["川乌","甘遂","藜芦","赤石脂","五灵脂"],"a":0,"e":"十八反半蒌贝蔹及攻乌，半夏反乌头，川乌与半夏同用属相反，故不宜同用。甘遂反甘草；藜芦反诸参、细辛、芍药；赤石脂畏肉桂；五灵脂畏人参，均非与半夏相反之物，其中与肉桂相畏者正是赤石脂"},{"q":"不宜与肉桂同用的药物是","o":["川乌","甘遂","藜芦","赤石脂","五灵脂"],"a":3,"e":"十九畏官桂善能调冷气，若逢石脂便相欺，肉桂与赤石脂相畏，不宜同用。川乌反半夏、瓜蒌等；甘遂反甘草；藜芦反人参、丹参诸参及细辛、芍药；五灵脂畏人参，均与肉桂无相畏关系，故唯赤石脂不宜与肉桂同用"},{"q":"防己、五加皮的共同功效是","o":["既能袪风湿，又能利水消肿","既能袪风湿，又能杀虫解毒","既能袪风湿，又能清肺化痰","既能袪风湿，又能清热解毒","既能袪风湿，又能活血通络"],"a":0,"e":"防己苦寒，功能祛风湿、止痛、利水消肿；五加皮辛苦温，功能祛风湿、补肝肾、强筋骨，兼能利水消肿，二者共同功效为祛风湿、利水消肿。祛风杀虫解毒多属白鲜皮、苦参；清肺化痰非祛风湿药所长；清热解毒如豨莶草；活血通络如威灵仙、伸筋草，均非二者共性"},{"q":"雷公藤、穿山龙的共同功效是","o":["既能袪风湿，又能利水消肿","既能袪风湿，又能杀虫解毒","既能袪风湿，又能清肺化痰","既能袪风湿，又能清热解毒","既能袪风湿，又能活血通络"],"a":4,"e":"雷公藤功能祛风除湿、活血通络、消肿止痛，穿山龙功能祛风除湿、活血通络、化痰止咳，二者均具祛风湿、活血通络之效。利水消肿为防己、五加皮所长；杀虫解毒仅雷公藤有之，穿山龙不备；清肺化痰虽穿山龙可化痰，然非雷公藤所有；清热解毒非二者共性"},{"q":"知母用于滋阴润燥，宜","o":["生用","炒用","炒焦用","蜜炙用","盐水炙用"],"a":4,"e":"知母苦甘寒，生用清热泻火、滋阴润燥，盐水炙后引药入肾，增强滋阴降火、润燥之力，故滋阴润燥宜盐水炙用。生用偏清气分实热；炒用、炒焦用多用于健脾或止血，非知母所长；蜜炙多用于补中或润肺止咳如甘草、款冬花，均非知母滋阴润燥之法"},{"q":"栀子用于凉血止血，宜","o":["生用","炒用","炒焦用","蜜炙用","盐水炙用"],"a":2,"e":"栀子生用苦寒，泻火除烦、清热利湿、凉血解毒；炒焦后寒性略减，偏入血分，增强凉血止血之功，故凉血止血宜炒焦用。生用重在清热泻火；盐水炙引药下行入肾，非栀子常用；蜜炙、炒用均非其凉血止血的规范炮制，栀子止血以炭品为要"},{"q":"属于“疗寒以热药”治疗原则的是","o":["用附子、干姜治疗腹中冷痛、脉沉无力","用茯苓、猪苓治疗水肿、小便不利","用黄芩、连翘治疗发热咽痛、舌红尿赤","用五味子、莲子治疗盗汗遗精","用麻黄、薄荷治疗外感表证"],"a":0,"e":"“疗寒以热药”属正治，即寒证用热药。附子、干姜辛热，温中散寒、回阳，用治腹中冷痛、脉沉无力之里寒证，正合此则。茯苓、猪苓利水渗湿；黄芩、连翘清热属“疗热以寒药”；五味子、莲子收敛固涩；麻黄、薄荷解表，均非疗寒以热药"},{"q":"属于“疗热以寒药”治疗原则的是","o":["用附子、干姜治疗腹中冷痛、脉沉无力","用茯苓、猪苓治疗水肿、小便不利","用黄芩、连翘治疗发热咽痛、舌红尿赤","用五味子、莲子治疗盗汗遗精","用麻黄、薄荷治疗外感表证"],"a":2,"e":"疗热以寒药指热证用寒凉药治疗，黄芩、连翘苦寒清热，治发热咽痛、舌红尿赤之热证。附子、干姜治腹中冷痛属疗寒以热药；茯苓、猪苓利水；五味子、莲子收敛固涩；麻黄、薄荷解表，均非寒药治热之例"},{"q":"天南星的药性是","o":["辛，温。有毒。归胃、肝经","辛，温。有毒。归脾、胃、肺经","苦，寒。有小毒。归肺、肝、心经","辛、咸，温。有小毒。归肺、大肠经","苦、辛，温。有毒。归肺、肝、脾经"],"a":4,"e":"天南星苦辛温，有毒，归肺、肝、脾经，功能燥湿化痰、祛风解痉、散结消肿，善治顽痰风痰。半夏为辛温有毒、归脾胃肺经，故辛温有毒归脾胃肺经是半夏之性；辛温有毒归胃肝经归经不符；苦寒有小毒与南星温性相反；辛咸温有小毒归肺大肠经亦非南星"},{"q":"半夏的药性是","o":["辛，温。有毒。归胃、肝经","辛，温。有毒。归脾、胃、肺经","苦，寒。有小毒。归肺、肝、心经","辛、咸，温。有小毒。归肺、大肠经","苦、辛，温。有毒。归肺、肝、脾经"],"a":1,"e":"半夏辛温有毒，归脾、胃、肺经，功能燥湿化痰、降逆止呕、消痞散结，为治湿痰要药。天南星为苦辛温有毒、归肺肝脾经，故苦辛温有毒归肺肝脾经属天南星；辛温有毒归胃肝经归经不符；苦寒有小毒与半夏温性相反；辛咸温有小毒归肺大肠经亦非半夏之性"},{"q":"煨法的目的是","o":["使药物质地松脆，易于粉碎","除去药物中的部分挥发油及刺激成分","改变药性，增强疗效或减少副作用","软化药材","矫味矫臭，利于服用"],"a":1,"e":"煨法将药物用湿面或湿纸包裹，置火灰中缓慢加热，目的是除去部分挥发油及刺激性成分，缓和药性、增强止泻作用，如煨肉豆蔻、煨木香。使质地松脆易粉碎是煅法；改变药性增强疗效或减少副作用为炙法、蒸法的通则；软化药材属润法、淋法；矫味矫臭多靠炒、炙、蒸"},{"q":"煅法的目的是","o":["使药物质地松脆，易于粉碎","除去药物中的部分挥发油及刺激成分","改变药性，增强疗效或减少副作用","软化药材","矫味矫臭，利于服用"],"a":0,"e":"煅法将药物置无烟炉火或耐火容器中煅烧，使质地松脆、易于粉碎并利于有效成分煎出，如煅石膏、煅牡蛎，部分药物煅后增强收敛。除去部分挥发油及刺激成分是煨法；改变药性增强疗效或减少副作用为炙法、蒸法；软化药材属水制润淋法；矫味矫臭多靠炒炙蒸，均非煅法主要目的"},{"q":"党参的归经是","o":["归肺、肾经","归脾、肺经","归脾、胃经","归心、肺经","归脾、肺、心、肾经"],"a":1,"e":"党参甘平，归脾、肺经，功能补中益气、健脾益肺、养血生津，为常用补气药。归肺、肾经非党参所属；归脾、胃经为白术、山药等；归心、肺经不符；归脾、肺、心、肾经过广，党参专入脾肺，故以归脾、肺经为准"},{"q":"白术的归经是","o":["归肺、肾经","归脾、肺经","归脾、胃经","归心、肺经","归脾、肺、心、肾经"],"a":2,"e":"白术苦甘温，归脾、胃经，功能健脾益气、燥湿利水、止汗、安胎，为健脾要药。归脾、肺经是党参；归肺、肾经不符；归心、肺经非白术所入；归脾、肺、心、肾经过泛，白术专入脾胃，故归脾、胃经为其标准归经"},{"q":"蛇床子的功效是","o":["燥湿截疟","祛除风痰","祛风止痛","解毒杀虫，疗疮","燥湿祛风，杀虫止痒"],"a":3,"e":"官方答案为【解毒杀虫，疗疮】，但依据教材，正确答案为【燥湿祛风，杀虫止痒】。蛇床子辛苦温、有小毒，功能燥湿祛风、杀虫止痒、温肾壮阳，主治阴肿阴痒、带下湿疮、疥癣及风湿痹痛。解毒杀虫疗疮是硫黄外用的功效，并非蛇床子所主，原答案张冠李戴，故不能成立"},{"q":"硫黄的功效是","o":["燥湿截疟","祛除风痰","祛风止痛","解毒杀虫，疗疮","燥湿祛风，杀虫止痒"],"a":4,"e":"官方答案为【燥湿祛风，杀虫止痒】，但依据教材，正确答案为【解毒杀虫，疗疮】。硫黄酸温有毒，归肾、大肠经，外用解毒杀虫疗疮，内服补火助阳通便，善治疥癣秃疮。燥湿祛风、杀虫止痒是蛇床子的功效，与硫黄不符，原答案错置，故不能成立"},{"q":"升浮药物大多具有的性味是","o":["味辛、甘，性温、热","味辛、甘，性寒、凉","味酸、苦、咸，性温、热","味酸、苦、咸，性寒、凉","味辛、酸，性寒、热"],"a":0,"e":"升浮药物多味辛、甘，性温、热，具升阳、发散、祛风、催吐等作用，趋向向上向外。味酸、苦、咸，性寒、凉为沉降药之性，主清热、泻下、降逆；辛甘凉、酸苦温及辛酸寒热等组合皆违背升降浮沉与性味的对应规律，非升浮药常规性味"},{"q":"沉降药物大多具有的性味是","o":["味辛、甘，性温、热","味辛、甘，性寒、凉","味酸、苦、咸，性温、热","味酸、苦、咸，性寒、凉","味辛、酸，性寒、热"],"a":3,"e":"沉降药物多味酸、苦、咸，性寒、凉，具清热、泻下、降逆、收敛、沉降作用，趋向内向下。味辛、甘，性温、热为升浮药之性，主升散；辛甘凉、酸苦温及辛酸寒热等配属错乱，均不符合沉降药的性味规律，故唯酸苦咸寒凉为是"},{"q":"三七的煎服法是","o":["先煎","后下","包煎","研末冲服","煎汤代水"],"a":3,"e":"三七甘微苦温，化瘀止血、活血定痛，有效成分不宜久煎，故多研末温开水冲服或入丸散，止血效佳。先煎用于矿石、贝壳及毒性药如石膏、附子；后下用于芳香易挥发药如薄荷、砂仁；包煎用于细小种子、花粉绒毛类如蒲黄、车前子；煎汤代水如灶心土、玉米须，均非三七用法"},{"q":"蒲黄的煎服法是","o":["先煎","后下","包煎","研末冲服","煎汤代水"],"a":2,"e":"蒲黄为香蒲科花粉，细小质轻，入水易漂浮、黏锅糊汤，故须包煎。先煎用于矿石贝壳类或毒性药；后下用于芳香挥发药如薄荷；研末冲服如三七；煎汤代水如灶心土、玉米须，均非蒲黄所宜。蒲黄生用行血化瘀、利尿，炒炭止血，入汤皆以包煎为法"},{"q":"患者经行不畅，经色紫黯夹血块，近1周又目赤肿痛，最宜选用的药是","o":["泽兰","丹参","川芎","茺蔚子","延胡索"],"a":3,"e":"茺蔚子辛苦微寒，功能活血调经、清肝明目，既治月经不调、经闭痛经，又能清肝火而疗目赤肿痛，一药两擅其长，故最宜。泽兰活血调经、利水消肿而无明目之功；丹参凉血活血、安神除烦；川芎活血行气、祛风止痛；延胡索活血行气止痛，均不能兼顾目赤"},{"q":"治疗肝火目赤肿痛，宜首选的药物是","o":["生地黄","玄参","牡丹皮","赤芍","紫草"],"a":3,"e":"赤芍苦微寒，归肝经，功能清热凉血、散瘀止痛，善清肝火，肝火上炎之目赤肿痛常首选。生地黄清热凉血、养阴生津；玄参凉血滋阴、解毒散结；牡丹皮清热凉血、活血散瘀并退虚热；紫草凉血活血、解毒透疹，虽皆入血分，但清肝明目之力均不及赤芍"},{"q":"治疗心阴虚证，宜首选","o":["石斛","百合","北沙参","南沙参","明党参"],"a":1,"e":"百合甘寒，归心、肺经，功能养阴润肺、清心安神，善治阴虚久咳及虚烦惊悸、失眠多梦等心肺阴虚之证，故心阴虚宜首选。石斛滋阴清热、益胃生津；北沙参、南沙参养阴清肺、益胃生津；明党参润肺化痰、养阴和胃，均偏于肺胃阴虚，少有清心安神之功"},{"q":"芫花的使用注意是","o":["不宜与硫黄、三棱同用","脾胃虚弱，食少便溏者忌用","不宜与牵牛子同用","不宜与甘草同用","不宜与巴豆同用"],"a":3,"e":"十八反藻戟遂芫俱战草，甘草反甘遂、大戟、海藻、芫花，故芫花不宜与甘草同用。不宜与硫黄、三棱同用的是芒硝，朴硝畏硫黄、牙硝畏三棱；脾胃虚弱、食少便溏忌用多为芦荟等苦寒药；不宜与牵牛子同用的是巴豆；不宜与巴豆同用的是牵牛子，皆非芫花所忌"},{"q":"芦荟的使用注意是","o":["不宜与硫黄、三棱同用","脾胃虚弱，食少便溏者忌用","不宜与牵牛子同用","不宜与甘草同用","不宜与巴豆同用"],"a":1,"e":"芦荟苦寒，归肝、大肠经，功能泻下通便、清肝泻火、杀虫疗疳，苦寒伤中，故脾胃虚弱、食少便溏者忌用。不宜与甘草同用的是甘遂、大戟、海藻、芫花；不宜与硫黄、三棱同用的是芒硝；不宜与牵牛子同用的是巴豆；不宜与巴豆同用的是牵牛子，均非芦荟所忌"},{"q":"反映药物影响人体阴阳盛衰倾向的中药性能是","o":["四气","五味","升降浮沉","归经","毒性"],"a":0,"e":"四气即寒、热、温、凉，反映药物影响人体阴阳盛衰、寒热变化的作用倾向，是概括药性阴阳属性的核心性能。五味指药物滋味及作用；升降浮沉反映作用趋向；归经示作用部位；毒性示毒烈有无，皆不直接反映阴阳盛衰之倾向，故能反映者为四气"},{"q":"反映药物作用部位的中药性能是","o":["四气","五味","升降浮沉","归经","毒性"],"a":3,"e":"归经指药物对脏腑经络的选择性作用，反映药物作用的部位。四气反映寒热温凉之药性与阴阳偏盛；五味反映滋味及行散、泄燥、收敛、软坚等作用特点；升降浮沉反映药物作用趋向；毒性反映对人体的毒害程度，四者皆非作用部位"},{"q":"辛味药物的作用是","o":["能行能散","能泄能燥","能收能敛","能渗能利","能软能下"],"a":0,"e":"辛味能行能散，有发散、行气、行血作用，多用于表证及气血阻滞。能泄能燥为苦味；能收能敛为酸味、涩味；能渗能利为淡味；能软能下为咸味，五味功用各异，与辛味行散之性判然有别"},{"q":"淡味药物的作用是","o":["能行能散","能泄能燥","能收能敛","能渗能利","能软能下"],"a":3,"e":"淡味能渗能利，有渗湿、利尿作用，多用于水肿、小便不利，如茯苓、薏苡仁。能行能散为辛味；能泄能燥为苦味；能收能敛为酸味；能软能下为咸味，均与淡味渗利之功不同，不可混淆"},{"q":"产于东北的道地药材是","o":["地黄、菊花","人参、五味子","薄荷、苍术","川芎、附子","茯苓、三七"],"a":1,"e":"东北为关药产区，道地药材有人参、五味子、细辛、防风、龙胆等，人参、五味子即其代表。地黄、菊花为河南怀药；薄荷、苍术多产江苏、安徽等地；川芎、附子为四川川药；茯苓、三七分产安徽、云南，均非东北道地药材"},{"q":"产于河南的道地药材是","o":["地黄、菊花","人参、五味子","薄荷、苍术","川芎、附子","茯苓、三七"],"a":0,"e":"河南为怀药产区，道地药材有地黄、山药、牛膝、菊花，合称四大怀药，地黄、菊花居其中。人参、五味子为东北关药；薄荷、苍术多产江苏、安徽；川芎、附子为四川川药；茯苓主产安徽、三七主产云南，均非河南道地"},{"q":"相恶的意义是","o":["性能功效相似药物配合应用，可以增强原有疗效的配伍","性能功效有部分共性的药物配合应用","一种药的毒副作用能被另一种药物减轻或消除的配伍","一种药物能减轻或消除另一种药毒性的配伍","一种药物能使另一种药物的功效降低或消失的配伍"],"a":4,"e":"相恶指一种药物能使另一种药物的功效降低甚至消失，如人参恶莱菔子。性能功效相似药配伍增强疗效是相须；性能功效有部分共性药配合是相使；毒副作用能被另一药减轻或消除是相畏；能减轻或消除另一药毒性是相杀，四者皆非相恶"},{"q":"相须的意义是","o":["性能功效相似药物配合应用，可以增强原有疗效的配伍","性能功效有部分共性的药物配合应用","一种药的毒副作用能被另一种药物减轻或消除的配伍","一种药物能减轻或消除另一种药毒性的配伍","一种药物能使另一种药物的功效降低或消失的配伍"],"a":0,"e":"相须指性能功效相似的药物配合应用，可增强原有疗效，如石膏配知母、大黄配芒硝。性能功效有部分共性的药配合是相使；毒副作用被另一药减轻或消除是相畏；能消除另一药毒性是相杀；使另一药功效降低或消失是相恶，均与相须不同"},{"q":"山药补气生津宜","o":["生用","土炒","麸炒","炒焦","盐水炒"],"a":0,"e":"山药甘平，归脾、肺、肾经，生用益气养阴、补气生津，用于气阴两虚及消渴等。麸炒后增强健脾止泻，故补脾止泻宜麸炒；土炒偏于补脾止泻安胎；炒焦助消化；盐水炒引药入肾以补肾，均非山药补气生津之法"},{"q":"山药补脾止泻宜","o":["生用","土炒","麸炒","炒焦","盐水炒"],"a":2,"e":"山药麸炒后增强健脾止泻之功，脾虚食少、泄泻便溏者宜之。生用偏于益气养阴、补气生津；土炒虽亦能补脾安胎，然山药止泻以麸炒为常法；炒焦助消化；盐水炒引药入肾补肾，均与山药健脾止泻的规范炮制不符"},{"q":"为了提高疗效，研成散剂冲服的是","o":["薄荷","三七","灶心土","玉米须","藏红花"],"a":1,"e":"三七有效成分遇高温易破坏且难溶于水，研末冲服可提高止血散瘀疗效，故宜研成散剂冲服。薄荷含挥发油，久煎失效宜后下；灶心土宜煎汤代水澄清洗胃肠；玉米须多煎汤代水服；藏红花宜泡服或另煎，均非研末冲服之品"},{"q":"为了保证疗效，不宜久煎的是","o":["薄荷","三七","灶心土","玉米须","藏红花"],"a":0,"e":"薄荷含挥发油如薄荷醇、薄荷酮，久煎则挥发油散失、药效降低，故须后下而不宜久煎。三七宜研末冲服；灶心土宜煎汤代水；玉米须多煎汤代水服；藏红花宜泡服或另煎，皆非因不宜久煎而设，与薄荷后下的机理不同"},{"q":"五味中能缓、能和的是","o":["苦","甘","辛","咸","酸"],"a":1,"e":"甘味能补、能缓、能和，有补益、缓急止痛、调和药性及和中作用。苦味能泄能燥且能坚；辛味能行能散；咸味能软能下；酸味能收能敛，涩味与酸味相近，均与甘味缓急和中之所主不同"},{"q":"五味中能燥、能泄的是","o":["苦","甘","辛","咸","酸"],"a":0,"e":"苦味能泄、能燥，泄有通泄、降泄、清泄之分，燥即燥湿，且能坚阴即泻火存阴。甘味能补能缓能和；辛味能行能散；咸味能软能下；酸味能收能敛，均与苦味泄燥之性相异，故燥泄当属苦"},{"q":"胸痹患者最应忌食","o":["辛辣、油腻、煎炸类食物","生冷食物","肥肉、脂肪、动物内脏等","鱼、虾、蟹、辛辣刺激性食物","不易消化的食物"],"a":2,"e":"胸痹多因胸阳不振、痰浊瘀阻，肥肉、脂肪、动物内脏等肥甘厚味易助湿生痰、壅滞血脉，加重胸闷疼痛，故最应忌食。辛辣、油腻、煎炸类多戒于脾胃湿热或疮疡；生冷食物伤阳；鱼虾蟹等发物为皮肤病所忌；不易消化食物泛用于脾胃虚弱，皆非胸痹核心忌口"},{"q":"皮肤病患者应忌食的是","o":["辛辣、油腻、煎炸类食物","生冷食物","肥肉、脂肪、动物内脏等","鱼、虾、蟹、辛辣刺激性食物","不易消化的食物"],"a":3,"e":"鱼、虾、蟹等海腥发物及辛辣刺激性食物易助风助湿、动血发痒，诱发或加重皮疹瘙痒，皮肤病患者当忌。辛辣、油腻、煎炸类偏于湿热疮疡；肥肉、脂肪、动物内脏为胸痹高脂所忌；生冷食物伤脾阳；不易消化食物宜于脾胃虚弱，均非皮肤病发物忌口之要"},{"q":"兼能补气的补阴药是","o":["黄精","玉竹","石斛","龟甲","百合"],"a":0,"e":"黄精甘平，归脾、肺、肾经，功能补气养阴、健脾润肺益肾，气阴双补，故为兼能补气的补阴药。玉竹养阴润燥、生津止渴；石斛益胃生津、滋阴清热；龟甲滋阴潜阳、益肾健骨、养血补心；百合养阴润肺、清心安神，均无补气之功"},{"q":"兼能养血的补阴药是","o":["黄精","玉竹","石斛","龟甲","百合"],"a":3,"e":"龟甲咸甘寒，归肝、肾、心经，功能滋阴潜阳、益肾健骨、养血补心、固经止血，兼具养血补心之效，故为兼能养血的补阴药。黄精补气养阴；玉竹养阴润燥；石斛滋阴清热、益胃生津；百合养阴润肺、清心安神，虽安心神却无养血之名"},{"q":"滑石入汤剂的适宜方法","o":["包煎","包煎、后下","先煎","包煎、先煎","后下"],"a":3,"e":"滑石为硅酸盐类矿物药，质地坚实且呈细粉状，入汤剂宜先煎使有效成分溶出，又须包煎以免粉末散入汤中难滤，故宜包煎、先煎。海金沙为孢子，细小轻浮易黏锅，只需包煎；后下用于芳香挥发药如薄荷，均与滑石的矿物粉末特性不同"},{"q":"海金沙入汤剂的适宜方法","o":["包煎","包煎、后下","先煎","包煎、先煎","后下"],"a":0,"e":"海金沙为海金沙科植物的干燥成熟孢子，细小如沙、质轻漂浮，入汤易浮于水面或黏锅糊汤，故须包煎。滑石为矿物细粉，宜包煎并先煎；后下用于薄荷、砂仁等芳香易挥发药；先煎用于矿石贝壳及毒性药，均非海金沙所需，其利水通淋以包煎为宜"},{"q":"大黄通便泻热，可","o":["釜底抽薪","润燥软坚","通利二便","杀虫疗疳","下气利水"],"a":0,"e":"大黄苦寒，功能泻下攻积、清热泻火、凉血解毒、逐瘀通经，借泻下以泄实热，恰如釜底抽薪，主治实热积滞便秘。润燥软坚是芒硝咸寒之性；杀虫疗疳为使君子、芦荟等驱虫药所长；通利二便、下气利水皆非大黄泻热通便的主要机理，故余项不符"},{"q":"芒硝泻下攻积，可","o":["釜底抽薪","润燥软坚","通利二便","杀虫疗疳","下气利水"],"a":1,"e":"芒硝咸苦寒，归胃、大肠经，功能泻下通便、润燥软坚、清火消肿，咸能软坚，善软化燥结大便，常与大黄相须治实热燥结。釜底抽薪是大黄泻热通便之喻；杀虫疗疳为使君子、芦荟等；通利二便、下气利水非芒硝软坚泻下之机理，均非其功"},{"q":"患者月经后期，经行腹痛，伴经期下肢水肿明显，最宜选用的药是","o":["泽兰","丹参","川芎","茺蔚子","延胡索"],"a":0,"e":"泽兰苦辛微温，功能活血调经、利水消肿，既治月经不调、经闭痛经，又消水肿，恰合经行腹痛兼下肢水肿之证。丹参凉血活血、安神除烦；川芎活血行气、祛风止痛；茺蔚子活血调经、清肝明目；延胡索活血行气止痛，均无利水消肿之功，不能兼顾水肿"},{"q":"麦冬的主要归经是","o":["肝、肾","心、脾","胃、肾","肺、肾","心、肺、胃"],"a":4,"e":"麦冬甘微苦微寒，归心、肺、胃经，功能养阴润肺、益胃生津、清心除烦，故归心、肺、胃。归肝、肾为枸杞子、女贞子等；归心、脾不符；归胃、肾为石斛；归肺、肾如黄精、山药之属，均非麦冬归经，其以心肺胃三经为核心"},{"q":"石斛的主要归经是","o":["肝、肾","心、脾","胃、肾","肺、肾","心、肺、胃"],"a":2,"e":"石斛甘微寒，归胃、肾经，功能益胃生津、滋阴清热，善治胃阴虚及肾阴虚证。归肝、肾为枸杞子、龟甲等；归心、脾不符；归肺、肾如黄精、山药；归心、肺、胃为麦冬，均非石斛归属，其专入胃、肾二经"},{"q":"北沙参、南沙参均具有的功效是","o":["滋补肝肾，明目","滋阴补血，生津润燥","养阴清肺，益胃生津","滋补肝肾，凉血止血","养阴润肺，清心安神"],"a":2,"e":"北沙参、南沙参均能养阴清肺、益胃生津，用于肺阴虚燥咳及热病津伤。滋补肝肾、明目为枸杞子、女贞子；滋阴补血、生津润燥非二沙参所有；滋补肝肾、凉血止血为墨旱莲；养阴润肺、清心安神为百合，均非南北沙参共有之效"},{"q":"枸杞子、女贞子均具有的功效是","o":["滋补肝肾，明目","滋阴补血，生津润燥","养阴清肺，益胃生津","滋补肝肾，凉血止血","养阴润肺，清心安神"],"a":0,"e":"枸杞子、女贞子均归肝、肾经，功能滋补肝肾、明目，主治肝肾阴虚、视力减退、腰膝酸软。养阴清肺、益胃生津为南北沙参；滋阴补血、生津润燥非二药所主；滋补肝肾、凉血止血为墨旱莲；养阴润肺、清心安神为百合，均非枸杞、女贞子共性"},{"q":"患者，女，34岁。胸中烦热，心悸不宁，失眠多梦，舌红苔黄，脉数。宜选","o":["朱砂配磁石","朱砂配黄连","朱砂配茯神","朱砂配丹参","朱砂配生甘草"],"a":1,"e":"胸中烦热、心悸失眠、舌红苔黄、脉数为心火亢盛、热扰心神，朱砂清心镇惊安神，黄连清心泻火，二者相配清心泻火、镇惊安神，最为宜。朱砂配磁石偏镇心安神、聪耳明目，治心肾不交；朱砂配茯神、丹参、生甘草虽可安神，清心泻火之力皆不及配黄连"},{"q":"目赤肿痛，翳膜遮睛，首选的药物是","o":["桑叶","蝉蜕","葛根","升麻","柴胡"],"a":1,"e":"蝉蜕甘寒，归肺、肝经，功能疏散风热、利咽开音、透疹止痒、明目退翳、息风止痉，善治风热目赤、翳膜遮睛。桑叶疏散风热、清肺润燥、清肝明目，无退翳之功；葛根解肌退热、生津升阳；升麻发表透疹、清热解毒、升举阳气；柴胡和解退热、疏肝升阳，均无明目退翳之效"},{"q":"孕妇宜慎用的药物是","o":["石膏","知母","芦根","栀子","天花粉"],"a":4,"e":"天花粉苦微寒，功能清热生津、清肺润燥、消肿排脓，因其有引产堕胎之弊，孕妇慎用，且反乌头。石膏、知母、芦根、栀子虽皆性寒凉，但无堕胎之虞，辨证使用不属孕妇慎用之列，故以天花粉为慎用之品"},{"q":"不宜与川乌、草乌、附子同用的药物是","o":["石膏","知母","芦根","栀子","天花粉"],"a":4,"e":"十八反半蒌贝蔹及攻乌，乌头反半夏、瓜蒌、贝母、白蔹、白及；天花粉即瓜蒌之根，故与川乌、草乌、附子同用属相反，不宜同用。石膏、知母、芦根、栀子虽皆清热泻火，但与乌头并无相反关系，唯天花粉当避"},{"q":"能温肺化痰，利气散结，长于治皮里膜外之痰的药物是","o":["芥子","陈皮","半夏","白附子","旋覆花"],"a":0,"e":"芥子辛温，归肺经，功能温肺化痰、利气散结、通络止痛，善温化寒痰，尤长治痰阻经络、皮里膜外之痰，如阴疽流注、肢体麻木。陈皮理气健脾、燥湿化痰，主脾胃湿痰；半夏燥湿化痰、消痞散结，治脏腑湿痰；白附子祛风痰、定惊搐；旋覆花消痰行水、降气止呕，均非皮里膜外之痰所主"},{"q":"能燥湿化痰，消痞散结，长于治脏腑湿痰的药物是","o":["芥子","陈皮","半夏","白附子","旋覆花"],"a":2,"e":"半夏辛温有毒，归脾、胃、肺经，功能燥湿化痰、降逆止呕、消痞散结，为治脏腑湿痰之要药，痰多咳喘、痰饮眩悸皆用之。芥子温肺化痰、利气散结，善治皮里膜外之痰；陈皮理气健脾、燥湿化痰；白附子偏祛风痰；旋覆花消痰行水、降气止呕，均非脏腑湿痰之主药"},{"q":"治胃火上炎之牙龈肿痛、头痛，常选用的药物是","o":["栀子","射干","夏枯草","鱼腥草","石膏"],"a":4,"e":"石膏甘辛大寒，归胃、肺经，功能清热泻火、除烦止渴，善清胃经实火，胃火上炎之牙龈肿痛、头痛常选之。栀子泻火除烦、清热利湿，清三焦之火；射干清热解毒、祛痰利咽，主咽喉肿痛；夏枯草清肝明目、散结消肿；鱼腥草清热解毒、消痈排脓，主肺热疮痈，均非胃火牙痛之主药"},{"q":"痰阻心窍，惊痫癫狂当选用","o":["龙骨","远志","磁石","合欢皮","柏子仁"],"a":1,"e":"远志辛苦温，归心、肾、肺经，功能安神益智、祛痰开窍、消散痈肿，能祛痰利窍，治痰阻心窍之惊痫癫狂。龙骨镇惊安神、平肝潜阳、收敛固涩；磁石镇惊安神、平肝潜阳、聪耳明目、纳气平喘；合欢皮解郁安神、活血消肿；柏子仁养心安神、润肠通便，均无祛痰开窍之功"},{"q":"情志抑郁，心神不宁当选用","o":["龙骨","远志","磁石","合欢皮","柏子仁"],"a":3,"e":"合欢皮甘平，归心、肝经，功能解郁安神、活血消肿，善解肝郁、悦心神，情志抑郁、心烦失眠、心神不宁者宜之。龙骨、磁石重镇安神，无解郁之功；远志祛痰开窍、安神益智，主痰阻心窍；柏子仁养心安神、润肠通便，主心阴虚失眠，均非疏肝解郁安神之品"},{"q":"能泻火存阴的药物多具有","o":["苦","咸","甘","辛","酸"],"a":0,"e":"苦味能泄、能燥、能坚，坚阴即泻火存阴，知母、黄柏苦寒泻相火而存肾阴即其例。咸味能软坚散结、泻下通便；甘味能补能缓能和；辛味能行能散；酸味能收能敛，均无泻火存阴即坚阴之性，故泻火存阴当属苦味"},{"q":"能软坚散结的药物多具有","o":["苦","咸","甘","辛","酸"],"a":1,"e":"咸味能软、能下，有软坚散结、泻下通便作用，如芒硝、海藻、昆布、牡蛎治瘰疬痰核、癥瘕痞块。苦味能泄能燥能坚，主泻火存阴；甘味能补能缓能和；辛味能行能散；酸味能收能敛，均非软坚散结之所主，故软坚散结当属咸味"}];
